INSERT INTO `forum_topics` VALUES (1,5,11,'Подготовка сайта','Разное',9,'tekushhie-raboty-na-saite','Текущие работы на сайте',4,NULL,'2012-06-09 16:34:00','2013-03-13 18:55:00','2026-07-11 15:37:57','2026-07-11 15:37:57'),(2,707,11,'Подготовка сайта','Разное',9,'prodvizenie-proekta','Продвижение проекта',3,NULL,'2013-06-03 21:38:00','2013-06-08 02:52:00','2026-07-11 15:37:57','2026-07-11 15:37:57'),(3,641,14,'Ноосфера','Исследования',514,'noosfera-stroenie-urovni-i-td','Ноосфера-строение, уровни и т.д.',24,NULL,'2013-02-03 14:14:00','2013-07-14 20:44:00','2026-07-11 15:37:57','2026-07-14 09:16:08'),(4,477,18,'Картины Учителей Ноосферы','Исследования',518,'kartiny-ucitelei-noosfery-1','Картины Учителей Ноосферы 1',1,NULL,'2012-07-10 21:33:00','2012-07-10 21:33:00','2026-07-11 15:37:57','2026-07-11 15:38:36'),(5,478,18,'Картины Учителей Ноосферы','Исследования',518,'kartiny-ucitelei-noosfery-2','Картины Учителей Ноосферы 2',22,NULL,'2012-07-10 21:39:00','2012-07-22 00:26:00','2026-07-11 15:37:57','2026-07-11 15:38:36'),(6,480,18,'Картины Учителей Ноосферы','Исследования',518,'voprosy-obsuzdeniia','Вопросы, oбсуждения',4,NULL,'2012-07-11 19:04:00','2012-08-21 20:52:00','2026-07-11 15:37:57','2026-07-11 15:38:36'),(7,506,20,'ВЦ Второго Кольца','Исследования',520,'socialnye-iavleniia-zemli-civilizaciia-zemli','Социальные явления Земли, цивилизация Земли',35,'Сообщения в этой теме — личные мнения и оценочные суждения их авторов, участников форума 2012–2019 годов, и не являются позицией владельца сайта. Владелец сайта не проверял и не подтверждает достоверность изложенных сведений. Тема публикуется в информационных и архивных целях как исторический документ дискуссии; она не является медицинской консультацией или рекомендацией и не может использоваться как руководство к действию. Сведения о здоровье, заболеваниях и способах лечения могут не соответствовать современным научным данным — по вопросам здоровья обращайтесь к врачу. Отдельные сообщения ставят под сомнение существование ВИЧ-инфекции; такие утверждения ошибочны и противоречат установленным научным данным: ВИЧ существует, без лечения приводит к СПИДу, а своевременная антиретровирусная терапия сохраняет здоровье и жизнь. Отказ от назначенного врачом обследования и лечения опасен для жизни. Отдельные сообщения затрагивают вопросы происхождения народов, религий и исторических событий и содержат конспирологические версии; эти суждения не являются установленными фактами, не отражают позицию владельца сайта и не имеют целью унизить достоинство какой-либо национальной, религиозной или иной группы.','2012-08-27 17:56:00','2017-10-30 18:43:00','2026-07-11 15:37:57','2026-07-23 12:19:51'),(8,476,3,'Душа','Исследования',503,'prodolzenie-proekta-dusa','Продолжение проекта \"ДУША\"',60,'Сообщения в этой теме — личные мнения и оценочные суждения их авторов, участников форума 2012–2019 годов, и не являются позицией владельца сайта. Владелец сайта не проверял и не подтверждает достоверность изложенных сведений. Тема публикуется в информационных и архивных целях как исторический документ дискуссии; она не является медицинской консультацией или рекомендацией и не может использоваться как руководство к действию. Сведения о здоровье, заболеваниях и способах лечения могут не соответствовать современным научным данным — по вопросам здоровья обращайтесь к врачу. Отдельные сообщения затрагивают вопросы происхождения народов, религий и исторических событий и содержат конспирологические версии; эти суждения не являются установленными фактами, не отражают позицию владельца сайта и не имеют целью унизить достоинство какой-либо национальной, религиозной или иной группы.','2012-06-07 09:53:00','2013-02-11 08:04:00','2026-07-11 15:37:57','2026-07-14 09:26:13'),(9,657,3,'Душа','Исследования',503,'volnovaia-genetika','Волновая генетика',7,'Сообщения в этой теме — личные мнения и оценочные суждения их авторов, участников форума 2012–2019 годов, и не являются позицией владельца сайта. Владелец сайта не проверял