INSERT INTO `glossary_terms` VALUES (1,'Посредники','posredniki','<div>Посредники - это ядро команды сайта - люди, с помощью которых производится выход на каналы связи с представителями Внеземного Разума и принимается уникальная информация по различным темам.</div>',NULL,'2026-07-08 05:32:26','2026-07-17 08:27:28'),(2,'Биоэкран','bioekran','<div>Биоэкран – высокоорганизованная часть полевой оболочки, контролирующая энергетические процессы в организме, выполняющая оценочно-регулирующие функции по отношению к процессу мышления, а также энергетически дублирующая головной мозг. Биоэкран фактически является нашим вторым, полевым, мозгом. С его помощью человек осуществляет двустороннюю связь с Ноосферой (см. Ноосфера), а также способен вступать в информационные контакты практически с любыми представителями Разумных Сил Космоса (см. Дальний Космос). Без преувеличения можно сказать, что данная энергоинформационная структура – окно человечества во внешний мир.</div>',NULL,'2026-07-08 05:32:26','2026-07-17 07:11:39'),(3,'Силы Ближнего и Дальнего Космоса','sily-bliznego-i-dalnego-kosmosa','<div>Силы Ближнего и Дальнего Космоса - рабочее название представителей внеземных цивилизаций, с которыми команда проекта устанавливала каналы связи.</div>',NULL,'2026-07-08 05:32:26','2026-07-17 08:34:20'),(4,'Внеземные Цивилизации (ВЦ)','vnezemnye-civilizacii','<div>Внеземные Цивилизации (ВЦ) - это классификация внеземных разумов, с которыми велось сотрудничество; подробная классификация опубликована в вики проекта. Подробнее в <a href=\"/wiki/vnezemnye-tsivilizatsii#_blank\">отдельной статье Вики.</a></div>',9,'2026-07-08 05:32:26','2026-07-17 08:28:12'),(5,'Оболочечный двойник','obolocecnyi-dvoinik','<div>Оболочечный двойник - это энергетический двойник человека; уникальная техника его сборки разработана А. Глазом в 1983-1986 годах для внетелесной работы и установления контактов.</div>',NULL,'2026-07-08 05:32:26','2026-07-17 08:32:24'),(6,'Хроносфера','xronosfera','<div>Хроносфера - проект исследований в области временных факторов, который разрабатывался в коллективе «Группы 3».</div>',NULL,'2026-07-08 05:32:26','2026-07-17 08:34:56'),(7,'Акупунктурные точки','akupunkturnye-tocki','Акупунктурные точки – участки меридианов, способные влиять на работу внутренних органов (см. также Меридианы и Энергопятна). Все энергоканалы меридианов пересекаются горизонтальными энергетическими опоясывающими кольцами, в районе которых плотность меридианного поля многократно возрастает. Находящиеся в зоне действия подобных колец участки меридианов влияют на внутренние органы, связанные с этими кольцами. Источник: Книга \"Сфера Разума\"',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(8,'Арсенал памяти больших полушарий','arsenal-pamiati-bolsix-polusarii','Арсенал памяти больших полушарий – совокупность вещественно-энергетических структур, воспринимающих, накапливающих, хранящих и перерабатывающих информацию в течение всей жизни человека, а также сами информационные накопления. Информационный банк человека. (см. Программы), (см. Стабилизирующие оси, Энергомосты). Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(9,'Блок видовых программ мозжечка','blok-vidovyx-programm-mozzecka','Блок видовых программ мозжечка – вещественно-энергетическая структура в мозжечке, содержащая информацию о строении и функционировании человеческого организма. Данный информационный банк в виде программ располагается в листках мозжечка (folia cerebelli) и периодически контролирует все органы и системы организма, устраняя появляющиеся в них нарушения. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(10,'Блуждающие импульсы','bluzdaiushhie-impulsy','<div>Блуждающие импульсы – полевые структуры, создаваемые специально или возникающие самопроизвольно и циркулирующие затем в коре головного мозга. Они способны переносить фрагменты информации между программами, а также образовывать новые программы из совокупности встречающейся на их пути «родственной» информации. Возможно возникновение подобных энергоинформационных структур и из активных информационных массивов, не прошедших обработку вследствие отсутствия необходимых программ. Такой массив повышает свою активность, становясь импульсом до востребования (см.) и запускает механизм программного накопления. Впоследствии на основе такого импульса создаётся новая программа для обработки информации в данной области.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:38:51'),(12,'Вращающийся диск биоэкрана','vrashhaiushhiisia-disk-bioekrana','<div>Вращающийся диск биоэкрана – энергоинформационное образование биоэкрана, основная функция которого – унификация энергоструктур, поступающих на биоэкран с 1-й и 3-й чакр, а также от организма. Другими его задачами являются координация информационного обеспечения отражённых стабилизирующих осей нижнего конуса биоэкрана и снятие информации с зеркально отраженных осей верхнего, а также коррекция нахождения биоэкрана в выбранном временном континууме. Биоэкран подбирает для конкретного интервала жизни человека гомологичные временные оси, учитывая возможности собственных подразделений, арсенальных наработок и кредовых составляющих.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:39:20'),(13,'Временные (темпоральные) тоннели','vremennye-temporalnye-tonneli','Временные (темпоральные) тоннели - структура, по строению сходная с временной осью, но более крупного порядка и не имеющая внутреннего заполнения. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(14,'Временные (темпоральные) факторы','vremennye-temporalnye-faktory','<div>Временные (темпоральные) факторы - особенности временных структур различных уровней организации, обусловленные свойствами составляющих их компонентов (виды временных энергий, их структура, количественные пропорции и др.). В зависимости от «элементарного состава» временной фактор во Вселенной условно можно разделить на пять уровней. К первому временному фактору относятся временные оси человека, ко второму - временные структуры планетарного масштаба, к третьему, четвертому и пятому - звездного, галактического и вселенского уровней соответственно. Особенности временных факторов обеспечивают уровневое разделение их информационного наполнения. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:42:12'),(15,'Временные (темпоральные) ключи','vremennye-temporalnye-kliuci','Временные (темпоральные) ключи - потенциально многомерные образования в районе 3-й чакры (базового энергоцентра) и полевого мозга, представленные набором констант и архивированных алгоритмов, определяющих принадлежность индивидуума к пространственному и временному континуумам (т.е. фиксируют его нахождение здесь и сейчас). Иногда на ключе может присутствовать информация временных факторов более высокого, чем планетарный, порядков, что дает возможность индивидууму воспринимать их информацию и взаимодействовать с их энергиями. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(16,'Временные (темпоральные) оси','vremennye-temporalnye-osi','<div>Временные (темпоральные) оси:&nbsp;<br>1) образования, состоящие из энергии и носителей физического времени, имеющие определённое информационное наполнение. Каждая ось несёт информацию о максимально вероятных событиях, которые должны произойти, если ей следовать. Форма временнoй оси напоминает спираль с диаметром поперечного сечения 1,5 мм. Основная точка приложения временных осей в организме человека – биоэкран. Во сне может происходить некоторое «заглядывание в будущее» по кредовым временным осям первого ноовременного фактора, на которых находится человек.&nbsp;<br>2) структура, образованная упорядоченным потоком темпоральной энергии и информационных корпускул времени - темпоров. Темпоральные структуры не имеют явного геометрического выражения в трехмерном пространстве, однако во временных измерениях ось обладает направленной протяженностью, границами и спирально закрученной внутренней структурой. Каждая ось определяет свой вероятностный коридор развития событий. В процессе жизни человек может оперировать одной либо одновременно несколькими осями. Временные оси определенным образом взаимодействуют с энергоинформационными структурами человека и оказывают влияние на процессы развития Души. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:26:01'),(17,'Временные факторы','vremennye-faktory','<div>Временные факторы – уровни разделения временных структур нашей Вселенной. Ноовременные факторы соответственно – относящиеся к человечеству. Первый ноовременной фактор соответствует временным осям конкретного человека, второй – планетарный. Далее – звёздный, галактический и, наконец, вселенский временной факторы. Геометрия 1-го ноовременнoго фактора следующая: временные составляющие осей, отклонённых вверх 3-й чакрой под влиянием кредового кольца биоэкрана (см.), выходят за пределы организма через биоэкран (см.). Они вплетаются в темпоральное поле 1-го ноовременнoго фактора со стороны спины, составляя его покров, или остов, и привнося в него поток информации. Темпоральный тор (см.) и темпоральная спираль 1-го ноовременнoго фактора не соприкасаются. Энергетическая составляющая отклонённых осей образует луч, поступающий на ноосферную инкарнационную ячейку (см.). Таким образом, сами временные оси, а также их временные составляющие, не попадают на ячейку. Туда направляется только инкарнационный луч (см.) – обязательный компонент данного процесса. Второй ноовременнoй фактор очень обширен и энергетически ёмок. Он включает в себя почти все энергоинформационные временные линии человечества. Второй ноовременнoй фактор содержит практически все уровни информации, которые существуют в Ноосферных и Космических структурах. На его осях хранится информация обо всём, но это не память поколений. Полевая оболочка человека использует только те оси, которые являются кредовыми, арсенальными или связаны с внешними воздействиями. Какие из временных осей будут использованы, зависит от перечисленных выше трёх информационных составляющих генокода и глобальных ситуационных всплесков 2-го ноовременнoго фактора, затрагивающих всю планету. Они могут пронизывать всю временнyю спираль планеты, воздействуя на временные факторы отдельных людей и человечества в целом. Дополнительно: книга \"ЗОМБИС\", гл. 2 и 3</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:43:33'),(18,'Дальний Космос (Силы Дальнего Космоса)','dalnii-kosmos-sily-dalnego-kosmosa','Дальний Космос (Силы Дальнего Космоса) – космические цивилизации, располагающиеся за пределами Солнечной системы, соответственно существуют и Ближний Космос (Силы Ближнего Космоса). Источники: Книги \"Сфера Разума\", \"Зомби\", \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(19,'Двойник, энергоинформационный (астральный двойник, оболочечный двойник)','dvoinik-energoinformacionnyi-astralnyi-dvoinik-obolocecnyi-dvoinik','<div>Двойник, энергоинформационный (астральный двойник, оболочечный двойник) - короткоживущее энергоинформационное образование, может сознательно, а иногда спонтанно создаваться человеком для сбора информации, коррекции, управления живыми и неживыми системами. Способен мгновенно перемещаться на любые расстояния, в различных пространствах и мерностях, а также во времени (прошлое, будущее) по различным временным факторам. В зависимости от выполняемых задач принимает форму шара или конической спирали (улитки). Может программироваться на выполнение одной или сразу нескольких задач. Временные рамки существования двойника ограничены поставленной задачей и возможностями оператора, создавшего собственный двойник, контролировать различные процессы. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:44:34'),(20,'Душа','dusa','<div>Душа - зарождающаяся в Ноосфере саморазвивающаяся универсальная система энергетических, пространственных и мерностных констант и переменных, обусловленных процессами развития базовых, т.е. элементарных, единиц, наполняющих пространство и названных первичными излучениями, или первоизлучениями. Душа объединяет в себе полевую оболочку, полевой мозг, темпоральный (Т) мозг и другие энергоинформационные единицы. Собственно, Душа - это свод названных составляющих на протяжении всей череды инкарнаций. Душа человека обладает обширными возможностями самообучения, саморазвития, самовыражения, реализации, самоопределения, сохраняя при этом лабильность, гибкость, способность к трансформации всех своих составляющих. Реализованная Душа, то есть завершившая цикл инкарнаций и достигшая совершенства, обретает возможность самоопределения - существовать ли ей в пределах родного Разума, принимать участие в жизни других Разумов или отправиться в свободный поиск во Вселенной. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:13:01'),(21,'Жизненное кредо','ziznennoe-kredo','Жизненное кредо – доминирующие жизненные установки человека, связанные с его генетическим и инкарнационным потенциалом, а также вся полученная в течение жизни информация, относящаяся к этим разделам. Основа этих установок закладывается в момент зачатия плода и поступления энергоинформационного сгустка из Ноосферы. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(22,'Зеркально отражённые стабилизирующие оси','zerkalno-otrazennye-stabiliziruiushhie-osi','Зеркально отражённые стабилизирующие оси – энергетические структуры в верхнем конусе биоэкрана, гомологичные отражённым осям его нижнего конуса (см. также Биоэкран и Стабилизирующие оси). Каждая такая структура специализируется на накоплении информации определённой кредовой направленности. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(23,'Импульсы до востребования','impulsy-do-vostrebovaniia','<div>Импульсы до востребования – вид блуждающих импульсов, специализированный для поиска информации. Стимулом для появления импульсов до востребования является текущая информация. Блуждающие импульсы до востребования циркулируют в мозге не постоянно, а генерируются в ситуациях, когда человеку нужно извлечь определённую информацию из арсенала памяти. Результатом их действия является закладка новой врeменной энергопрограммы в районе одной из стабилизирующих осей. Вначале программа довольно коротка, но постепенно в неё достраивается информация, относящаяся к данной теме. Если человек достаточно «вжился» в проблему, то произведённый импульс продолжает существовать длительное время. Он может перейти из врeменного в относительно постоянный, и тогда циркулирование такого импульса и сбор им информации может продолжаться дни, месяцы и даже годы.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:49:13'),(24,'Инкарнационные фильтры','inkarnacionnye-filtry','<div>Инкарнационные фильтры – структуры Ноосферы, уничтожающие в информационном банке человека после его смерти негативную информацию. Процесс стирания на фильтрах информации приближается к человеческому понятию ада, так как при этом обрабатываемая энергоинформационная структура в какой-то степени продолжает ощущать себя человеком. При прохождении оболочкой 1-го фильтра идёт грубая очистка и компоновка её энергетики. На 2-м фильтре происходит более тонкая идентификация и обработка информации. Информационное построение арсенальной структуры после смерти напоминает ветвистое дерево, в густой кроне которого могут «прятаться» грехи – отрицательные программы. При прохождении инкарнационных фильтров вся «больная ветвь» уничтожается, так что если подобный дефект располагался у главного ствола, то будет утрачено много полезной информации. В самом тяжёлом случае от информационных накоплений может практически ничего не остаться. Во время таинства исповеди отрицательные программы перемещаются на самые крайние «веточки», что сводит информационные потери к минимуму. Источник: Книга \"Сфера Разума\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:15:48'),(25,'Инкарнационная информация','inkarnacionnaia-informaciia','Инкарнационная информация: Информационные накопления прошлых жизней. Источник: Книга \"Сфера Разума\" Инкарнационная информация - знания и навыки в виде программных комплексов и алгоритмов, наработанные в предыдущих воплощениях, способные активизироваться и достраиваться при поступлении сходных информационных фрагментов. В зависимости от рода деятельности человека в текущей жизни могут пробудиться или нет, а активизировавшаяся, особенно в юном возрасте, инкарнационная информация воспринимается как способности или дарование, талант. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(26,'Инкарнационный луч','inkarnacionnyi-luc','<div>Инкарнационный луч – энергоструктура, соединяющая в процессе жизни человека его полевую оболочку с инкарнационной ячейкой (см. Ноосферная инкарнационная ячейка). Данный луч является комплексом тонких энергий, несущих составляющие 1-й и 3-й чакр, и поддерживает двустороннюю связь с инкарнационной ячейкой. На протяжении первых 7–8 см луч не разделяется с временными осями. Далее, после разделения, он представлен «тяжёлыми» энергосубстанциями 1-й чакры и информационными следами временных осей, несущими информацию о положении полевой оболочки человека во временнoм континууме.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:50:24'),(27,'Инкарнационная ячейка','inkarnacionnaia-iaceika','<div>Инкарнационная ячейка - сложный индивидуальный комплекс в Ноосфере, который хранит информацию о прошлых жизнях и Душу между инкарнациями. Основа энергоинформационной структуры человека, совместно Душой эволюционирующая в составе планетарного Разума. Ячейка представлена двумя мерностно разделенными, но неразрывно связанными составляющими - хранителем и последователем. Последователь обеспечивает накопление и хранение в неизменном виде нарабатываемой в течение каждой жизни информации, сохраняет постоянную связь Души с Ноосферой, является коммутационным узлом при перемещениях энергоинформационного двойника. Хранитель находится в изолированной (вне времени и пространства) метрике Ноосферы и является пристанищем Души между инкарнациями. Хранитель содержит полный архив предыдущих информационных накоплений, пополняемый в моменты смерти индивидуума, служит защищенным вместилищем информации Души, а также обладает набором служебной, навигационной и прочей информации, необходимой для ее существования и развития. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:14:13'),(28,'Инкарнация','inkarnaciia','<div>Инкарнация:&nbsp;<br>1) обретение энергоинформационной структурой человека, вещественной (телесной) «оболочки». Образующаяся при этом система собственно и является человеком См. также Реинкарнация. Кодирование – наложение на несущую основу специфических сигналов для достижения определённой цели. Система таких сигналов является кодом. Сигналами же могут служить временные, энергетические, пространственные или физические параметры, влияющие на функционирование программ. Источник: Книга \"Сфера Разума\".&nbsp;<br>2) Инкарнация (воплощение Души) - период активного состояния инкарнационной ячейки, или жизнь человека от момента оплодотворения яйцеклетки (и одновременного поступления Души из Ноосферы), до возврата Души обратно в инкарнационную ячейку после смерти индивидуума. См. также реинкарнация. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:20:22'),(29,'Информационно-энергетическая структура мозжечка','informacionno-energeticeskaia-struktura-mozzecka','<div>Информационно-энергетическая структура мозжечка - образование, содержащее эталонную информацию о функционировании и организации всех тканей, органов, систем, а также полевой структуры человека. Это банк эталонной информации, обеспечивающей оптимальное существование организма человека. Функциональная единица данного образования наиболее адекватно описывается термином «программа». Под программой здесь понимается энергоинформационный комплекс, связанный в единое структурное образование, отражающее характеристики функциональных единиц органов и систем. На основе эталонных программ осуществляется периодический контроль работы организма; при выявленных отклонениях включается система коррекции. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:02:49'),(30,'Космические Силы','kosmiceskie-sily','Космические Силы - Разумные системы, космические цивилизации, а также проекции, созданные ими для своих целей, обладающие достаточным количеством информации, энергии, времени и др. для совершенствования, поддержания жизни, восполнения, воспроизводства. Также имеющие возможности без ущерба вышеназванному оказывать влияние на внешние (относительно себя) процессы. Формы жизни разнообразны, и соответствие даже самым смелым представлениям не обязательно. Источники: Книги \"Зомби\", \"Сфера Разума\", \"Книга Живы\"',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(31,'Красные квант-глюинные пары','krasnye-kvant-gliuinnye-pary','Красные квант-глюинные пары - «элементарные кирпичики» информационных программных комплексов головного мозга человека, наиболее энергетически плотные и информационно стабильные. Образованы поле-информационными квантами - элементарными «субчастицами» - и глюинами - калибровочными частицами полево-информационного взаимодействия (от «глю» - клей, «ин» - информация, т.е. буквально - «связывающие информацию»). Источник: Книга \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(32,'Кредовое кольцо биоэкрана (кредовое кольцо полевого мозга)','kredovoe-kolco-bioekrana-kredovoe-kolco-polevogo-mozga','Кредовое кольцо биоэкрана (кредовое кольцо полевого мозга) – кольцевая энергетическая структура биоэкрана, составляющая основание его нижнего конуса и охватывающая черепную коробку в области лба. Данное образование участвует в информационном обмене, переработке информации, выполняет защитные функции и задаёт кредовый энергетический фон, направляющий процессы мышления. Вырабатывает качественную энергетическую составляющую для кредовых программ. Активно влияет на процессы мышления. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(33,'Кредовые программы','kredovye-programmy','Кредовые программы - расположенные в глубоких слоях информационного банка больших полушарий энергоинформационные программные комплексы, несущие доминирующие жизненные основы человека, связанные с его генетическим и инкарнационным потенциалом, а также вся полученная в течение жизни информация, относящаяся к этим разделам. Основа этих установок - результирующая составляющая из базовых программ прошлых жизней. В данной инкарнации закладывается в момент зачатия плода и поступления энергоинформационного сгустка из Ноосферы. Источники: Книги \"Сфера Разума\", \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(34,'Курация','kuraciia','<div>Курация (человека конструктивной Космической Силой) - принятие КС ответственности за результаты действий человека в течение текущей жизни или на протяжении нескольких жизней, и предполагает ответственность за жизнь и душевное развитие человека. Это не снимает ответственности с человека в случаях нарушения им законов причинно-следственных зависимостей, но может благоприятно ска- заться на проработке негативных кармических зависимостей прошлых жизней. Курация возникает в случае совпадения устремлений и дествий человека и КС. В случаях всех конструктивных КС обязательно двустороннее выраженное осознанное согласие о будущих действиях с разъяснением со стороны КС общих задач, перспектив и т.д. Тем самым соблюдаются основы свободы выбора. На большую часть человечества распространяется курация Учителей Ноосферы. Примечание. Курация человека деструктивными Силами предполагает совершенно иные взаимоотношения. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:21:09'),(35,'Луч 6-й чакры (базового энергоцентра)','luc-6-i-cakry-bazovogo-energocentra','<div>Луч 6-й чакры (базового энергоцентра) - энергоструктура, сознательно развиваемая и активизируемая человеком для получения информации и управления, коррекции живых и неживых систем. Может быть несфокусированным, чего достаточно для сбора информации на близком расстоянии, либо сфокусированным. Сфокусированный луч 6-й чакры может использоваться для получения информации (например, диагностика состояния организма на расстоянии, прослеживание ситуаций, разведка и др.), управления (моделирования) живыми и неживыми системами, процессами, ситуациями, магического оперирования достаточно высокого порядка (в т.ч. с построением синхронного канала обратной связи). Для эффективной работы требуется серьезная подготовка оператора, возможно, в нескольких жизнях. Луч 6-й чакры может использоваться совместно с 3-й и 7-й чакрами (базовыми энергоцентрами) для оперирования во временном континууме, иных пространствах и мерностях. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:10:09'),(36,'Луч инкарнационый','luc-inkarnacionyi','Луч инкарнационый - сложное смешение энергий, где присутствуют темпоральные субстанции и самые легкие, тонкие энергии полевого мозга, равно как и энергии ноосферных структур и Ближнего космоса. Энергетическое и темпоральное насыщение имеет переменную плотность. Луч опускается от инкарнационной ячейки до уровня полевого мозга и 7-й чакры индивидуума. Присутствует на протяжении всей жизни. По инкарнационному лучу происходит двусторонний обмен информацией между людьми и Учителями Ноосферы. Источники: Книги \"Зомби\", \"Сфера Разума\", \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(37,'Меридианное поле','meridiannoe-pole','<div>Меридианное поле – ячеистая энергоинформационная структура, охватывающая весь организм человека. Располагается на границе подкожно-жировой клетчатки и мышечного слоя. Каркас меридианного поля составляет энергетика продолговатого мозга. Активность и площадь ячеек меридианного поля различна: она уменьшается по направлению к конечностям и голове, увеличиваясь в районе околопупочного кольца. В точках пересечения сторон ячеек находятся энергопятна. Энергетический потенциал пятен может изменяться при патологиях в связанных с ними органах. Основная функция меридианного поля – гомеостатическая. При определённых условиях с его помощью возможен переток энергии с одного участка на другой, что приводит к изменениям в текущих метаболических процессах.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:26:28'),(38,'Меридианы','meridiany','Меридианы – области меридианного поля, где на единице площади количество ячеек меридианного поля максимально, а размеры самих ячеек минимальны. Меридианы напоминают электрические кабели, покрывающие всю площадь человеческого тела, по которым постоянно циркулируют энергоинформационные потоки (см. Меридианное поле). Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(39,'Мерности','mernosti','Мерности - ресурсы пространства, отличающиеся топологией, константами физических законов и разделенные энергетическими барьерами. Отдельные мерности пространства недоступны для Разумов до определенных ступеней развития, когда они, Разумы, смогут оперировать константами и коэффициентами собственных своих временных ключей и других структур, фиксирующих их существование в конкретном пространственном и временном континиуме. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(40,'Метагалактический домен','metagalakticeskii-domen','Метагалактический домен - скопление некоторого числа галактик, объединенных по каким-либо принципам. Метагалактический домен имеет внутренние особенности (временные, пространственные, мерностные, энергетические), не выходящие за рамки вселенских Космических законов, но отличающие его от других Метагалактических доменов и до поры препятствующие каким-либо взаимодействиям. Находящиеся в нем разумные системы (Космические Силы) обладают потенциалом для создания общих информационных банков и могут использовать ресурсы домена для своего развития. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(41,'Нитевидные энергетические структуры биоэкрана','nitevidnye-energeticeskie-struktury-bioekrana','Нитевидные энергетические структуры биоэкрана – полевые образования, наиболее отчётливо проступающие в остове нижнего конуса, простираясь от кредового кольца к перешейку, и представленные двумя составляющими – временной и энергоинформационной. Данные структуры разделяют биоэкран на секторы. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(42,'Ноосфера','noosfera','<div>Ноосфера:&nbsp;<br>1) в процессе эволюции человека с помощью Сил Дальнего Космоса была сформирована колоссальная энергоинформационная структура, объединяющая всё человечество в единый «организм». Руководствуясь Космическими Законами и полностью им соответствуя, Ноосфера контролирует эволюцию человечества, направляя его в русло формирования сообщества, также соответствующего этим Законам. Данное образование имеет сложное многоуровневое строение, каждый уровень которого представлен характерными для него носителями интеллекта – Учителями (см.). Верхние этажи этой «пирамиды» связаны с различными Силами Дальнего Космоса и в общепринятых человеческих понятиях смыкаются с представлениями о Боге. Данная «Сфера Разума» перекликается с гениальным предвидением Вернадского, поэтому по традиции названа Ноосферой. Источник: Книга \"Сфера Разума\".</div><div>2) Ноосфера - сложная разумная энергоинформационная структура, соответствующая Космическим Законам и способствующая эволюции человечества, способная к развитию и совершенствованию как самостоятельно, так и совместно с планетарным Разумом. По развитию и скорости информационного обмена на порядок опережает человеческое сообщество. Ноосфера создана конструктивными Силами Дальнего Космоса, в т.ч. как основа для создания единого планетарного разума, Соборной Души Разума. Обладает сложной эшелонированной структурой, функционально разделенной по уровням. Населена персонализированными составными монадами (Учителями). Имеет в составе сложные временные и энергетические структуры, банки информации. Осуществляет паритетный информационный обмен с другими Разумными системами Ближнего и Дальнего Космоса. Источник: \"Книга Живы\".</div><div><br></div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:21:11'),(43,'Ноосферная инкарнационная ячейка','noosfernaia-inkarnacionnaia-iaceika','<div>Ноосферная инкарнационная ячейка – энергоинформационная структура в нижнем слое Ноосферы, несущая переработанную и систематизированную информацию, накопленную во всех прожитых человеком жизнях и обеспечивающая инкарнационные циклы. Инкарнационная ячейка может находиться в двух состояниях – активном (состояние Реинкарнации (см.)) или пассивном, когда энергоинформационная структура Биоэкрана с Инкарнационной информацией (см.) находится в ней, готовясь к новому воплощению в оплодотворённую яйцеклетку, наиболее подходящую по микроэлементному составу. В активном состоянии между инкарнационной ячейкой и организмом связанного с ней человека поддерживается информационный обмен через инкарнационный луч (см.), выходящий через 7-ю чакру. Собственно ячейка, или ячейка-хранитель, находится за инкарнационным фильтром (см.), а перед ним расположена её голографическая копия, или ячейка-последователь.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 07:27:00'),(44,'Нулевой меридиан','nulevoi-meridian','Нулевой меридиан – срединные передний и задний меридианы, образующие кольцо и составляющие основу каркаса меридианного поля. С этим меридианом связаны практически все органы, поэтому он очень удобен для диагностики.',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(45,'Общий энергофон','obshhii-energofon','<div>Общий энергофон – это изменяющаяся с течением времени информационно-энергетическая направленность процессов в головном мозге. Этот общий вектор оказывает влияние на кредовое кольцо биоэкрана (см.)– энергетическую структуру, контролирующую деятельность головного мозга, в том числе и поток проходящей через него информации. Общий энергофон – категория не только энергетическая, но и биохимическая. Его направленность, или код, задают стволовые структуры головного мозга – ретикулярная формация, а биохимические структуры, постоянно циркулирующие в области мозолистого тела, взаимодействуя с ним, образуют как бы его вещественный слепок. Их полевые структуры, складываясь, формируют суммарное поле, по форме напоминающее вытянутую коническую спираль. Раструб её приходится на лобные доли, а острый конец – на мозжечок. Данное образование есть энергетический слепок общего энергофона.</div><div>Остов биоэкрана не одинаков в нижнем и верхнем конусах биоэкрана (см.). Остов нижнего конуса построен из полевых копий хромосомного набора человека. В верхнем конусе остовом являются полевые структуры, представляющие собой зеркальные отражения «хромосом» нижнего конуса, на которых сохранены участки, несущие информацию об индивидуальных особенностях арсенала памяти (см.) конкретного человека.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 06:45:52'),(46,'Параллельные миры','parallelnye-miry','Параллельные миры – миры, находящиеся в других измерениях.',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(47,'Первичные излучения, первоизлучения','pervicnye-izluceniia-pervoizluceniia','Первичные излучения, первоизлучения - базовые алгоритмы, являющиеся протоматерией, или элементарной средой строения Вселенной. Генерации первоизлучений в различных комбинациях и пропорциях, а также их взаимодействия образуют все многообразие воспринимаемых и пока еще не известных человеку фундаментальных физических категорий. Источники: Книги \"Сфера Разума\", \"Книга Живы\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(48,'Перешеек биоэкрана','pereseek-bioekrana','Перешеек биоэкрана – наиболее узкая часть биоэкрана, не превышающая в диаметре 5–7 см, и располагающаяся на расстоянии 10–15 см от его нижнего кольца. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(49,'Подчерепной энергококон','podcerepnoi-energokokon','<div>Подчерепной энергококон – энергетическая структура, окутывающая головной мозг человека между его корою и костью черепной коробки, не захватывая при этом продолговатый мозг. Подчерепной энергококон выполняет функции, перекликающиеся с работой стабилизирующих осей (см.). Его поле стремится придать хаотическому движению блуждающих импульсов (см.) упорядоченность и стабильность, что достигается их дозированной подпиткой энергией или за счёт их стабилизации в период бодрствования. Данное поле имеет четыре основных пика в форме конических спиралей, два из которых расположены в передней части мозга, в лобных долях, а два – в височных областях.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:11:07'),(50,'Полевая оболочка','polevaia-obolocka','<div>Полевая оболочка – максимально энергонасыщенная полевая резонансная зона человека, образованная сфокусированными излучениями органов, систем и организма в целом, взаимодействующая с окружающей средой и являющаяся частью Ноосферы (см.). Она несёт информацию как об организме, так и о взаимодействии данного человека с Ноосферой. Оболочка имеет три выраженные зоны: электромагнитную защитную зону, являющуюся её внешним слоем, зону биологического кольцевого экранирования, сформированную излучениями генетического, молекулярного и биологического характеров, и термозону, образованную в основном инфракрасным излучением. В зоне экранирования постоянно собирается информация о текущем состоянии организма, то есть фокусируются излучения, исходящие от органов, клеток и белковых соединений.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:11:42'),(51,'Полевая структура в виде ниспадающего «водопада»','polevaia-struktura-v-vide-nispadaiushhego-vodopada','<div>Полевая структура в виде ниспадающего «водопада» – защитная полевая структура, предохраняющая биоэкран (см.). Она возникает: при смене кредовых установок в арсенале памяти (см.) в ходе определения программ, несущих максимально кредовый характер, при активизации 2-й чакры во время первого в жизни человека полового акта, в процессе подготовки организма к смерти как последняя попытка стабилизации энергоструктур человека. Источниками «водопада» являются «обесточенные» программы арсенала памяти. Полевое завихрение нижнее – полевая структура в нижней части полевой оболочки (см.), имеющая форму вертикальной вытянутой воронки. Программа – информационный комплекс на носителе, связанный в единое образование рядом признаков, отражающих отличительную черту какого-либо предмета или явления.</div>',NULL,'2026-07-10 03:52:46','2026-07-17 08:12:35'),(52,'Программа','programma','Программа - под программой здесь понимается энергоинформационный комплекс, связанный в единое структурное образование, отражающее характеристики функциональных единиц органов и систем. На основе эталонных программ осуществляется периодический контроль работы организма; при выявленных отклонениях включается система коррекции. Программа – информационный комплекс на носителе, связанный в единое образование рядом признаков, отражающих отличительную черту какого-либо предмета или явления. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:46','2026-07-10 03:52:46'),(53,'Резонирующее кольцо биоэкрана','rezoniruiushhee-kolco-bioekrana','Резонирующее кольцо биоэкрана – энергоинформационное образование, поддерживающее информационный обмен между кольцами биоэкрана. Оно обрабатывает информационные комплексы, которые проходят через биоэкран на ноосферную инкарнационную ячейку, а также обеспечивает обработку энергоинформационных фрагментов 1-й и 3-й чакр и защищает внутренние формирования биоэкрана от агрессии через чакры. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:47','2026-07-10 03:52:47'),(54,'Реинкарнация','reinkarnaciia','<div>Реинкарнация: процесс передачи информации с ячейки-хранителя на плод, а также переход ноосферной инкарнационной ячейки в активное состояние в связи с переносом энергоинформационной структуры биоэкрана на развивающуюся биомассу оплодотворённой яйцеклетки. См. также Инкарнация. <br>Процесс активизации инкарнационной ячейки при новом воплощении Души, сопровождающийся воссозданием инкарнационного луча и постепенной передачи по нему на эмбрион всех архивированных алгоритмов Души. Источники: Книги \"Сфера Разума\", \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:47','2026-07-17 08:33:51'),(55,'Рейшей','reisei','Рейшей - посев, распространение, в определенных пространствах - упорядочивание первооснов, или структуры, мироздания согласно замыслу Творца. Управление всей комбинаторикой первоэлементов с обязательным упорядочиванием, дающим основы для создания Разумных систем (на общекосмическом языке). Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:47','2026-07-10 03:52:47'),(56,'Ромбовидная линза','rombovidnaia-linza','<div>Ромбовидная линза – вещественно-полевая структура, по своей геометрии напоминающая два конуса с общим основанием. Ромбовидная линза расположена под гипоталамусом, так что вершина первого конуса входит в гипоталамическую структуру, а вершина второго ориентирована по направлению к гипофизу. Молекулярная структура ромбовидной линзы представлена связанными между собой концентрическими ансамблями высокомолекулярного соединения. Основная функция ромбовидной линзы – обработка информации полинуклеотидной матрицы дневного информационного накопления с последующим разрушением её материального носителя.</div>',NULL,'2026-07-10 03:52:47','2026-07-17 08:13:24'),(57,'Смерть','smert','Смерть – процесс подготовки энергоструктуры человека к существованию в автономном режиме, запускаемый в момент клинической смерти.',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(58,'Соборная Душа Разума','sobornaia-dusa-razuma','Соборная Душа Разума - состояние полностью осознанного сосуществования; содействие, содружество, совместное развитие всех либо большинства людей, Душ и Ноосферных структур. Соборная Душа - стержень энергетических и информационных процессов объединенного Разума, обеспечивающий корректность и быстроту взаимодействий со всеми Разумными единицами и внутренней временной структурой. Качественный показатель уровня развития разумной системы. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(59,'Стабилизирующие оси больших полушарий и биоэкрана','stabiliziruiushhie-osi-bolsix-polusarii-i-bioekrana','<div>Стабилизирующие оси больших полушарий и биоэкрана – шесть высокоэнергетичных образований вещественно-полевой природы в полушариях головного мозга и столько же аналогичных полевых структур в каждом из конусов биоэкрана (см.). Вещественная часть мозговых стабилизирующих осей выглядит как цепи нейронов, а собственно оси образованы белково-полисахаридными молекулами. Стабилизирующие оси больших полушарий настраивают работу арсенальных структур, стимулируя обработку информации заданного энергетического фона, выполняют поисковые и координирующие функции.<br><br>Функции полевых образований в нижнем и верхнем конусах биоэкрана связаны с работой головного мозга. Если он пополнился информацией за счёт работы, например, первой стабилизирующей оси больших полушарий мозга, то аналогичные процессы произойдут на нижнем и верхнем конусах биоэкрана. Основная функция отражённых стабилизирующих осей нижнего конуса – обеспечение взаимосвязи процессов в арсенале памяти и на биоэкране. Они распределяют информацию по биоэкрану и осуществляют обратную связь с арсенальными программами по кредовым позициям, а также контролируют энергетическое равновесие между биоэкраном и головным мозгом.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 07:29:41'),(60,'Сторожевые импульсы','storozevye-impulsy','<div>Сторожевые импульсы – циркулирующие по коре больших полушарий частицы, всегда имеющие биохимическую основу небольшой молекулярной массы и выполняющие две основных функции: энергетическую подпитку программ и дополнительный перенос информации с одной программы на другую или со стабилизирующих осей (см.) на программы. Подобный информационный обмен часто заканчивается возникновением новой программы. Сторожевые импульсы создаются, как правило, неосознанно и довольно быстро теряют энергию, поэтому вынуждены пополнять её за счёт транспортных соединений, приносимых кровью. Периодически, по мере обесточивания, они разрушаются и создаются снова из транспортных биохимических частиц, которые приносятся с биологическими жидкостями мозга.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:14:37'),(61,'Сторожевые мозжечковые импульсы','storozevye-mozzeckovye-impulsy','<div>Сторожевые мозжечковые импульсы – энергетические всплески над незаполненными или нестабильными участками мозжечковых программ. Это своеобразные «мостики» в недостроенных программных кольцах.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:22:24'),(62,'Суперструна','superstruna','Суперструна - состояние пространства в виде неразвернутой информационной матрицы, существующей относительно других пространств как не взаимодействующая с пространственными объектами протяженная структура исчезающее малых размеров, но с огромной плотностью энергии. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(63,'Темпоральная энергия','temporalnaia-energiia','Темпоральная энергия - силовая составляющая сущности времени. Имеет различные устойчивые состояния, обусловливающие особенности свойств временных факторов. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(64,'Тетрады энергетических копий хромосом (лепестков)','tetrady-energeticeskix-kopii-xromosom-lepestkov','Тетрады энергетических копий хромосом (лепестков) – полевые структуры биоэкрана, состоящие из энергетических копий хромосом, объединённых в группы по четыре, и являющиеся функциональными единицами его остова. Каждая такая группа – тетрада – способна вмещать большой объём информации, например, данные об энергетическом обеспечении органа или системы. Информационная насыщенность тетрад увеличивается к перешейку биоэкрана. Между тетрадами имеются переходные блоки. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(65,'Торы биоэкрана','tory-bioekrana','<div>Торы биоэкрана – данные структуры появляются в биоэкране (см.) человека на 3–5 году жизни и являются результатом накопления и систематизации информации. Они выполняют следующие функции.</div><ol><li>Обеспечивают взаимодействие верхнего и нижнего конусов биоэкрана.</li><li>Являются стыковочным узлом при обмене информацией двух биоэкранов.</li><li>Расшифровывают информацию, полученную на энергетическом уровне из внешней среды.</li><li>Энергетически защищают остов и биоэкран в целом своими полями, увеличиваясь в объёме или «распыляя» энергию с последующим созданием специфического защитного облака.</li><li>Усредняют или активизируют информацию конусов биоэкрана.</li><li>Способны адаптировать и передавать информацию друг другу.</li></ol>',NULL,'2026-07-10 03:52:48','2026-07-17 08:15:20'),(66,'Тор темпоральный','tor-temporalnyi','<div>Тор темпоральный – энергоструктура, образующаяся в результате взаимодействия полевой оболочки человека с диском 3-й чакры и временными осями. Временные составляющие осей создают темпоральное поле, которое выходит из диска 3-й чакры, охватывая туловище человека и распространяется сверху до района мозжечка, а снизу до раструба 1-й чакры. Диск 3-й чакры, смещаясь к соматическим структурам, образует нишу, что превращает данное эллипсовидное образование в тор. По физической сущности он ближе всего к электромагнитным полям, хотя это иной вид поля. Темпоральный тор выполняет три функции: стабилизирует оболочку на временнoм факторе, косвенно обеспечивает энергией 2-й слой полевой оболочки и может использоваться для внешнего Космического управления. Темпоральный тор пронизывает все три слоя полевой оболочки человека, но обычно не выходит за её пределы. В состоянии покоя он способен увеличиваться, что смещает диск 3-й чакры на максимальное расстояние от тела человека. Это придаёт оболочке бoльшую лабильность, увеличивая её способность к перемещению.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 07:30:45'),(67,'Точка сборки (ТС)','tocka-sborki-ts','<div>Точка сборки (ТС) - это словосочетание пришло от К. Кастанеды писателя эзотерика. Человеческое тело не может существовать без тонких, окружающих его структур. Такие структуры, образно говоря, можно назвать коконом человека. Этот кокон находится под влиянием внешних сил и имеет своеобразное строение. ТС - точка сборки, это некое пространство, некая точка отсчета, некое начало структуры кокона. При смещении ТС, смещается мир восприятия реальности, смещается сознание и осознание самого себя в неком временном пространстве. Грубо говоря, как радиоприемник, подстраивается под длину волны, так и ТС подстраивается под восприятие мира, тем самым, меняя его вокруг нас в нашем восприятии. При определенной практике, можно научится сдвигать ТС в ту или иную сторону.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:16:10'),(68,'Установочные линзы таламуса','ustanovocnye-linzy-talamusa','<div>Установочные линзы таламуса – парные таламические структуры, по форме напоминающие усечённые конусы. От окружающей ткани их отличает поляризация вещества. Установочные линзы весьма лабильны, т.к. на них влияют («устанавливают») нуждающиеся в информации активные программы арсенала памяти, изменяя их поляризацию. На установочных линзах таламуса происходит сортировка информационных фрагментов полинуклеотидных цепей, сформированных на зрительных трактах. Участки цепей, в зависимости от текущей поляризации линз, могут проходить через них или откалываться на их границах. Цепи, прошедшие установочные линзы, составляют остов будущей полинуклеотидной матрицы дневного информационного накопления. Отколовшиеся короткие структуры, несущие фрагменты информации, направляются в арсенал памяти самостоятельно.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:16:54'),(69,'Учителя','ucitelia','<div>Учителя:&nbsp;<br>1) представители Сил Ближнего Космоса; энергоинформационные сущности Ноосферы (см.). Учителя первого порядка представляют собой конгломерат из семи Ноосферных инкарнационных ячеек (см.), обладают мощным интеллектом и способны существовать несколько тысячелетий. Формирование первой такой структуры завершилось ко времени рождения Христа. Учителя полностью отвечают Космическим Законам. Они обладают определённой индивидуальностью, позволяющей выполнять каждому из них только ему присущие функции. Всего таких структур около трёхсот.&nbsp;<br>2) Учитель - разумная монада Ноосферы Источник: \"Книга Живы\".<br>3) обобщённое название конструктивных сущностей: архангелы, ангелы-хранители и т.п.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:25:44'),(70,'Чакры','cakry','<div>Чакры:&nbsp;<br>1) стабильные образования энергоструктуры человека, обеспечивающие энергетический баланс в организме за счёт обмена с внешней и внутренней средой, поддерживающие этим функционирование как отдельных органов, так и организма в целом. Кроме энергетических через чакры проходят также и информационные потоки. Источник: Книга \"Сфера Разума\".<br>2) Чакры (базовые энергоцентры организма) - комплекс из семи многофункциональных динамичных полевых образований, обеспечивающих энергетический баланс органов, энергетических структур и организма в целом за счёт обмена с внешней средой. С точки зрения эволюционного развития каждый энергоцентр можно представить как узкополосный резонатор - камертон, настраивающий информационно-эмоциональный (душевный) резонанс человека для согласования с процессами, происходящими как между индивидуумами, так и во внешней среде, что подразумевает отклик на возмущения планетарного и космического порядков. Чакры, как правило, располагаются в границах тела. Являются связующим звеном между организмом и окружающей средой, и из существующего разнообразия видов и спектров энергий отбирают, усваивают необходимые и удаляют ненужные или вредные для данного человека энергетические фрагменты (следствия болезней, внешней агрессии и др.). В свою очередь, эти шлаки могут утилизироваться другими организмами или неживыми системами. Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:23:06'),(71,'Шамбала','sambala','Шамбала - энергоинформационный банк Ноосферы, контролируемый Учителями 6-го порядка. Источник: Книга \"Сфера Разума\". Шамбала - традиционное название энергоинформационного банка Ноосферы, где хранится подробная информация о планете, всех населявших ее расах, сущностях, обо всех исторических фактах в динамике развития. Максимально защищенная и недоступная для посторонних вмешательств структура. Охраняется, поддерживается и корригируется Учителями Ноосферы. Не имеет физической (материальной в нашем понимании) проявленности. Источник: \"Книга Живы\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(72,'Эгрегор','egregor','<div>Эгрегор - энерго-информационно-временная структура, возникающая при сонаправленных действиях группы людей с общими устремлениями. Эгрегор также может создаваться и корректироваться Ноосферой или Конструктивными Силами. Существуют различные эгрегоры: религиозные, родоплеменные, клановые, магических орденов, некоторых философских учений, творческих школ, длительно и целеустремленно работающих коллективов, социальных движений и др. Происходит постоянное взаимное развитие эгрегора и индивидуумов через обмен информацией и энергиями, что способствует ускорению общего развития Разума. Сказанное нельзя применить в отношении деструктивных эгрегоров (масонства, различных сект, культов и пр.). Источник: \"Книга Живы\".</div>',NULL,'2026-07-10 03:52:48','2026-07-17 07:35:02'),(73,'Эмоция','emociia','Эмоция – сложный комплекс процессов, протекающих в головном мозге, для которого характерен энергетический фон, индуцируемый программами арсенала памяти, мозжечковыми программами, энергетической напряжённостью подчерепного энергококона и энергетическим воздействием извне. Важнейшую роль в данной системе играют гормоны. Внешне эмоции выражаются в виде психических переживаний и определённого настроя. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(74,'Энергетические мосты (энергомосты)','energeticeskie-mosty-energomosty','Энергетические мосты (энергомосты) – незамкнутые кольцевые энергоцепи между стабилизирующими осями больших полушарий, отражающие энергетические следы стабильно протекающих в коре информационных процессов. Энергомосты упорядочивают движение блуждающих импульсов, стабилизируя этот процесс. Они формируются по энергоследу какого-либо устойчиво повторяющегося, стабильного акта логического мышления. Источник: Книга \"Сфера Разума\".',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(75,'Энергетические «улитки»','energeticeskie-ulitki','Энергетические «улитки» – часто встречающиеся в окружающем мире и энерго-структуре человека устойчивые полевые структуры в виде вытянутых конических спиралей.',NULL,'2026-07-10 03:52:48','2026-07-10 03:52:48'),(76,'Энергетический дубликат полевой оболочки (оболочечный двойник, астральный двойник)','energeticeskii-dublikat-polevoi-obolocki-obolocecnyi-dvoinik-astralnyi-dvoinik','<div>Энергетический дубликат полевой оболочки – при высокой энергонасыщенности полевой оболочки человека и отсутствии патологических отклонений в организме может происходить формирование, отрыв и перемещение по темпоральным осям в прошлое или будущее энергетического сгустка – дубликата полевой оболочки. При темпоральном перемещении дубликат оболочки вначале имеет форму, близкую к шару, а затем преобразуется на временной оси в энергетическую структуру в форме конической спирали. С помощью такой «машины времени» человек способен «путешествовать» как во времени, так и в пространстве, преодолевая гигантские расстояния.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 07:35:50'),(77,'Энергетические пятна (энергопятна)','energeticeskie-piatna-energopiatna','<div>Энергетические пятна (энергопятна) – области, где пересекаются несколько меридианов. Через энергопятна меридианного поля из центральной нервной системы поступают сигналы, корректирующие работу связанных с ними органов. Через эти образования осуществляется связь соматических структур организма с его энергоинформационными системами (полевой оболочкой, чакрами, биоэкраном), а также гормональной системой. Энергетические пятна могут иметь форму горизонтальных опоясывающих колец. В таких структурах плотность энергетики меридианного поля многократно возрастает. Энергопятна имеют стабильное местоположение, но не постоянны по энергетической ёмкости. Их энергия способна приобретать различные «оттенки», что позволяет влиять как внутренним органам на центральные управляющие системы, так и наоборот. Головной мозг и гормональная система посредством энергопятен меридианного поля воздействуют на органы, оболочку, чакровые структуры и биоэкран.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 07:52:28'),(78,'Энергоинформационный двойник человека (“двойник над головой”)','energoinformacionnyi-dvoinik-celoveka-dvoinik-nad-golovoi','<div>Энергоинформационный двойник человека (“двойник над головой”) – малоизученный энергетический след соматики человека, по форме напоминающий перевёрнутое вниз головой человеческое тело. Его «голова» совмещена с головой человека так, что 7-я чакра «двойника» совпадает с 5-й чакрой человека. «Двойник» является одним из ключевых энергетических моментов в каббалистических знаниях. Обычно он присутствует над человеком, хотя и не всегда. При определённых условиях сознание человека может переходить в «двойника», что позволяет осуществлять связь с «параллельными мирами».</div>',NULL,'2026-07-10 03:52:48','2026-07-17 08:19:16'),(79,'Ядро инкарнационной ячейки','iadro-inkarnacionnoi-iaceiki','<div>Ядро инкарнационной ячейки – центральная сферическая структура ноосферной инкарнационной ячейки (см.), являющаяся её энергетическим опознавательным знаком и определяющая индивидуальность конкретного человека в конкретной жизни. Последняя прожитая жизнь накладывает определённые штрихи на фокусирующую сердцевинную структуру ядра. Изначально оно дается «пятнистым» и «тёмным», не гомогенным. Цель развития энергоструктуры человека – равномерное распределение энергии по всем уровням ячейки, которые располагаются в виде концентрических колец вокруг ядра, а также глубинным структурам самого ядра. После заполнения всей структуры энергией, близкой к эталону хотя бы на 80 %, происходит её качественное изменение и переход на более высокий уровень Идеала, отвечающий всем космическим требованиям. Такая эволюция ячейки и является целью инкарнационных циклов. При этом возможен переход ячейки в разряд Учителей, что не исключает в дальнейшем существование в белковой форме. Ядро инкарнационной ячейки напоминает оглавление книги, которую мы заполняем, глава за главой, своими жизнями.</div>',NULL,'2026-07-10 03:52:48','2026-07-17 07:36:10'),(80,'Видение','videnie','<div>Видение - получение расширенного (от стандартно воспринимаемого человеком обычными органами чувств) объема информации о пространстве, времени и объектах, в них находящихся. Видение - нелинейный, многоуровневый и многовариантный процесс, в той или иной степени связанный с другими - оперативной возможностью подключения к ноосферным структурам, информационным банкам и т.д. для получения расширенной информации. Видение доступно абсолютному большинству людей, но, как всякий тонкий процесс, требует определенных навыков. У некоторых людей, приобретавших такие навыки в течение не одной жизни, видение может проявиться спонтанно и неожиданно, иногда в раннем возрасте. Видение может быть реализовано, во-первых, через луч 6-й чакры, с помощью сформированного энергоинформационного двойника - во-вторых, может эффективно дополнять режим обычного зрения, если у человека врожденно обуслов- лено некоторое смещение потоков информации от зрительных трактов в-третьих. Существуют и другие, более сложные способы видения и методы восприятия расширенного спектра информации, связанные с активизацией 7-й чакры и некоторых программ полевого мозга.</div>',NULL,'2026-07-17 06:31:05','2026-07-17 08:19:47'),(81,'Жива','ziva','<div>Жива - свод этических законов вселенского развития; принципы Ноосферы. Подробнее в <a href=\"/library/kniga-zivy-starodumov-ilia-starodumova-elmira-sokolov-vadim#_blank\">\"Книга Живы\"</a>.</div>',NULL,'2026-07-17 06:33:13','2026-07-17 08:28:45'),(82,'Инки','inki','<div>Инки - условное название Космической Силы. Гуманоидный Разум, расположенный в галактике М 33 (созвездие Треугольника). Высокоразвитая цивилизация сбалансированного (духовного и техногенного) пути развития. Индивидуумы очень похожи на людей. Инки произошли от другого гуманоидного Разума, расположенного далеко за пределами нашего Метагалактического домена. В районе Ближнего (для нас) космоса имеют энергетическую проекцию. Входят в Коалицию Разумов. По отношению к нашему Разуму выполняют профессорские функции, санкционированные Координаторами и другими Разумами Коалиции. Длительное время предоставляют информацию духовно развивающего и технического направлений.</div><div>В период расцвета цивилизации земных Инков корабль Инков космических потерпел аварию, и вынужденно приземлился на их территории. Космические Законы предписывают невступление в общение на начальных этапах развития, но волею случая некоторое время несколько индивидуумов общались с землянами (о чем сохранились предания). Спустя годы к ним пришла помощь, и они смогли вернуться на родину. Физические следы пребывания были уничтожены. С тех пор в прямой (физический) контакт с землянами не вступали. Источник: \"Книга Живы\".</div>',193,'2026-07-17 06:35:32','2026-07-17 08:20:36'),(84,'Координаторы','koordinatory','<div>Координаторы - Космическая Сила, трансформировавшийся древнейший планетарный Разум, в настоящее время - хранители свода законов, норм и правил конструктивного развития разумной жизни. Являют собой манифестацию общевселенских законов, принципов и норм. В нашем Метагалактическом домене Координаторы являются высшей инстанцией в принятии решений глобального характера, а также во всех случаях, относящихся к нарушениям баланса закона причинно-следственных зависимостей и ряда других. Любое решение Координаторов является обязательным к реализации всеми входящими в Коалицию Разумами. Источник: \"Книга Живы\".</div>',NULL,'2026-07-17 06:40:49','2026-07-17 08:30:11'),(85,'Космическое Сообщество (Коалиция)','kosmiceskoe-soobshhestvo-koaliciia','<div>Космическое Сообщество (Коалиция) - Космические Силы, имеющие общие цели и задачи и объединенные разноплановыми информационными банками. В Коалицию входят 17 Разумов разнообразных форм жизни, не считая Координаторов и Разведку Дальнего Космоса. Разум Земли пока не входит в Коалицию. Источник: \"Книга Живы\".</div>',NULL,'2026-07-17 06:42:15','2026-07-17 08:30:41'),(86,'Лимбическая система','limbiceskaia-sistema','<div>Лимбическая система - совокупность механизмов головного мозга, создающих, в частности, эмоциональный настрой; работа лимбической системы определяет текущее состояние общего энергетического фона.</div>',NULL,'2026-07-17 06:42:59','2026-07-17 08:20:55'),(87,'Полевой мозг','polevoi-mozg','<div>Полевой мозг - управляющая энергоинформационная структура, охватывающая головной мозг и возвышающаяся над ним. Полевой мозг дублирует и в ряде случаев контролирует головной, регулируя процессы мышления и энергетические процессы в организме. Полевой мозг может осуществлять информационный обмен с другими разумными системами, но сведения об этих событиях редко покидают пределы бессознательного уровня. Источник: \"Книга Живы\".</div>',NULL,'2026-07-17 07:02:50','2026-07-17 07:02:50'),(88,'Разведка Дальнего Космоса (РДК)','razvedka-dalnego-kosmosa-rdk','<div>Разведка Дальнего Космоса (РДК) - сообщество разумных индивидуумов, каждый из которых обладает информацией, возможностями и полномочиями всего Разума. Разум РДК трансформировался, как и Координаторы, для решения общих задач и ныне наделен ресурсами Координаторов и Совета Коалиции. Наряду с абсолютными для нашего домена оперативностью и мобильностью, имеет практически неограниченные полномочия для принятия самостоятельных решений и все необходимые ресурсы для их реализации. Источник: \"Книга Живы\".</div>',NULL,'2026-07-17 07:05:30','2026-07-17 07:05:30'),(89,'Союзники','soiuzniki','<div>Союзники - условное название Разума энергоинформационных (материально не проявленных в нашем понимании) сущностей. Союзники являются производным от индивидуумов Плазмоидов - немногочисленной разумной общности, обитающей непосредственно в Солнце. Можно сказать, что Союзники - это реализованные Души индивидуумов Плазмоидов. Союзники - идеально сконфигурированные многоуровневые мобильные сгустки-индивидуумы, наделенные Разумом. Симбиотическая особь из 12 индивидуумов являет собой разумную единицу, проходящую путь становления и развития. Разумные единицы объединяются в эшелонированные полевые структуры с внутренней нелинейной природой информационного обмена - разумную Систему Союзников. Источник: \"Книга Живы\".</div>',NULL,'2026-07-17 07:09:23','2026-07-17 07:09:23');
