INSERT INTO `pages` VALUES (300,14,'Сеанс с Силами 20140205','seans-s-silami-20140205','Проект: \'\"Ноосфера -11\" Взаимодействие Ноосферы с людьми Дата: 5 февраля 2014 годa Ведущий: Олег Силы 2 Кольцо Посредник Елена ВОПРОС: Как организовано информационное и энергетическое взаимодействие…',NULL,'<div><figure data-trix-attachment=\"{&quot;alignment&quot;:&quot;right&quot;,&quot;contentType&quot;:&quot;image&quot;,&quot;height&quot;:140,&quot;url&quot;:&quot;/storage/media/archive/8b8fb5524dba709605e0f931.png&quot;,&quot;width&quot;:200}\" data-trix-content-type=\"image\" class=\"attachment attachment--preview\"><img alt=\"Изображение к материалу «Сеанс с Силами 20140205» - №1\" src=\"/storage/media/archive/8b8fb5524dba709605e0f931.png\" width=\"200\" height=\"140\"><figcaption class=\"attachment__caption\"></figcaption></figure><table>\n<tbody><tr>\n<td><strong>Проект</strong>:\n</td>\n<td><em>\"Ноосфера -11\" Взаимодействие Ноосферы с людьми</em>\n</td></tr>\n<tr>\n<td><strong>Дата:</strong>\n</td>\n<td>5 февраля 2014 годa\n</td></tr>\n<tr>\n<td><strong>Ведущий:</strong>\n</td>\n<td>Олег\n</td></tr>\n<tr>\n<td><strong>Силы</strong>\n</td>\n<td>2 Кольцо\n</td></tr>\n<tr>\n<td><strong>Посредник</strong>\n</td>\n<td>Елена\n</td></tr>\n</tbody></table></div><div><strong>ВОПРОС:</strong> Как организовано информационное и энергетическое взаимодействие человека с Учителями со стороны Ноосферы, и какие уровни Учителей взаимодействуют с людьми? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия человека и Ноосферы, данное взаимодействие происходит через инкарнационную ячейку. В принципе, не имеет никакой роли это ячейка Последователь или ячейка Хранитель. Так как, информация хранится в этих двух ячейках и дублируется. В принципе, такой же уровень взаимодействия осуществляется и со стороны Изосферы. Непосредственно человеческая единица подвязана на два луча. Как на Ноосферу, так и на Изосферу. Взаимодействие происходит непосредственно с Учителями первого и, частично, второго порядка, что со стороны Ноосферы, так и со стороны Изосферы. Но со стороны Изосферы более интенсивно взаимодействует только первый уровень Учителей. <br><br><strong>ВОПРОС:</strong> Если мы ведём речь о точке подключения к Ноосфере через седьмую чакру, луч, выходящий на инкарнационную ячейку - это подключение к Ноосфере? <br><strong>ОТВЕТ:</strong> Да, к Ноосфере. <br><br><strong>ВОПРОС:</strong> А к Изосфере? <br><strong>ОТВЕТ:</strong> Через отражённого двойника. <br><br><strong>ВОПРОС:</strong> Через отражённого, то есть перевёрнутого, по сути дела? <br><strong>ОТВЕТ:</strong> Да. <br><br><strong>ВОПРОС:</strong> Этот луч идёт с третьей чакры? <br><strong>ОТВЕТ:</strong> Да, с третьей. Хотя здесь зависит и от того, каким образом расположен двойник в текущей инкарнации у человека. <br><br><strong>ВОПРОС:</strong> Разве бывают моменты когда двойник, может быть повернут под другим углом? <br><strong>ОТВЕТ:</strong> Да, все верно. <br><br><strong>ВОПРОС:</strong> Я понимаю, что это исключение, а от чего это может зависеть? <br><strong>ОТВЕТ:</strong> Это зависит от нескольких факторов. Первым фактором является - насколько человек относится к Изосфере, насколько он близок к Изосфере, так вернее будет сказать. Вторым основополагающим фактором является программа. Программа, которую на данный момент отрабатывает индивид. Программы могут меняться по прошествии времени с интервалом в несколько лет. Индивид должен нарабатывать и отрабатывать программы как касающиеся развития Ноосферных структур, так касающиеся развития и Изосферных структур. <br><br><strong>ВОПРОС:</strong> И ещё момент касающийся Изосферы. Правильно ли я вас понимаю, что Изосфера и Ноосфера, если брать в некотором воспринимаемом нами пространственно временном континууме, находятся практически в одном и том же, скажем, месте, не точке? Они совмещены, скажем так? <br><strong>ОТВЕТ:</strong> Не совсем совмещены. <br><br><strong>ВОПРОС:</strong> Тогда как правильно? <br><strong>ОТВЕТ:</strong> Если рассматривать мерности, составляющие планетарное измерение, то по своему месту нахождения Ноосфера и Изосфера фактически граничат, но, находятся в разных плоскостях в разных плотностях. <br><br><strong>ВОПРОС:</strong> То есть, речь идёт о том, что они находятся в разных измерениях? У них разная частота колебания устойчивого состояния? <br><strong>ОТВЕТ:</strong> Да, всё верно. <br><br><strong>ВОПРОС:</strong> Все понятно. Спасибо. Дальше, следующий вопрос. Форма взаимодействия с человеком. Какие и когда формы взаимодействия применяются? Через группу людей, отдельных индивидуумов, через Эгрегоры, через инкарнационную ячейку, другие формы взаимодействия? Если взаимодействие через инкарнационную ячейку, то через ячейку Хранитель или ячейку Последователь? <br><strong>ОТВЕТ:</strong> Что касается ячейки. Вся информация о текущей инкарнации находится в ячейке Последователе. Но одновременно она дублируется в ячейке Хранителе. Поэтому какого-то глобального разделения в ячейках, по текущей инкарнации, не происходит. Взаимодействие, в основном, идёт через ячейку Последователь. Что касается взаимодействия учительской системы с человеком. Основное, как мы уже говорили ранее, это взаимодействие непосредственно через саму ячейку. Также взаимодействие с человеком идет с помощью эгрегориальных структур и непосредственно через окружающее пространство, именно не пространство - время, а пространство. В пространстве существуют некие точки, через которые, как при помощи рычагов, идет воздействие на человека. <br><br><strong>ВОПРОС:</strong> То есть, это возможно некие поля, да? Или программы в полевой форме? <br><strong>ОТВЕТ:</strong> Это точки, на которые Ноосфера либо Изосфера может давить, и будут происходить определенные события. <br><br><strong>ВОПРОС:</strong> Скажем так – это какие-то полевые образования, которые позволяют без непосредственного воздействия, а через опосредованное воздействие, подвинуть человека в этой инкарнации к тем или иным действиям. Да? <br><strong>ОТВЕТ:</strong> Близко. <br><br><strong>ВОПРОС:</strong> Хотел бы уточнить. Вот у нас есть прямая форма взаимодействия. К примеру, человек взаимодействует по лучу со своей ячейкой Последователь и через неё с Хранителем. С эгрегореальными структурами как это происходит? Луч идёт конкретно от эгрегориальной структуры, через седьмую чакру, к примеру, на биоэнергокристалл или на биоэкран? Или Эгрегор использует луч, идущий на ячейку, и взаимодействие проходит через ячейку? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия эгрегориальных структур с человеком здесь достаточно иметь небольшое количество энергии данного эгрегора, для того, чтобы происходило взаимодействие. Что касается озвученной формы привязки по лучу, то здесь не видим никакого взаимодействия. Достаточно, как мы уже только что сказали, иметь причастность энергетически. <br><br><strong>ВОПРОС:</strong> То есть, чтобы совпадали вибрации, так? <br><strong>ОТВЕТ:</strong> Если в энергетике индивидуума будет находиться даже 5% энергетики эгрегориальной структуры, то уже будет происходить взаимодействие. Непосредственной привязки по лучу не происходит. <br><br><strong>ВОПРОС:</strong> Если я вас правильно понял, то здесь можно вернуться к тому понятию, которое ранее существовало до, скажем так, материалистической теории. Это понятие эфира. То есть некое распространение, скажем грубо, что-то вроде радиоволн, неких волновых посылов, импульсов, которые находят те души, так? У которых есть либо эти программные комплексы, либо эти закладки, либо совпадает по вибрациям, и тогда происходит взаимодействие, так? <br><strong>ОТВЕТ:</strong> Да все верно. <br><br><strong>ВОПРОС:</strong> А обратное взаимодействие. От души к эгрегориальной структуре. В такой же форме или это по принципу отражения, отражённого луча? <br><strong>ОТВЕТ:</strong> Всю ту информацию, которую прорабатывает в себе человек и изменения его энергетики - они автоматически отражаются в эгрегоре. То есть, получается энергетика человека несёт часть энергетики эгрегора. И они, как единое целое, взаимосвязаны. Но при этом, у человека существует ещё дополнительно один вариант взаимодействия с не очень крупным эгрегором. Это нахождение двух эгрегоров в одном большом и в другом, менее значимом. Это допускается, но не более. <br><br><strong>ВОПРОС:</strong> Но, я, всё-таки, прошу прощения, хотел бы ещё раз уточнить. Обратная взаимосвязь от человека к эгрегору происходит по принципу отражённого луча? Или по принципу - душа сама испускает определённые волны? <br><strong>ОТВЕТ:</strong> По принципу прямой взаимосвязи. <br><br><strong>ВОПРОС:</strong> Всё-таки, эта программка? Создаётся некая программка, которая в ответ и посылает эти лучи, импульсы? <br><strong>ОТВЕТ:</strong> Происходит синхронизация энергетики индивидуума и энергетики эгрегориальной структуры. <br><br><strong>ВОПРОС:</strong> Хорошо, а если мы коснёмся Изосферы. То, взаимосвязь – подобна, как с Ноосферой или есть какие - то особенности? Как структуры? <br><strong>ОТВЕТ:</strong> Здесь есть определённые существенные различия. В данном случае, если эгрегориальная структура курируется непосредственно Изосферными структурами, то здесь более плотный контроль над количеством объёма энергии дублируемой эгрегором на величину, значительно превышающую количество энергии, которое взаимодействует с Ноосферными структурами. То есть, здесь эти объёмы доходят, в некоторых случаях, от 15 до 20-23 процентов. Можно сказать, другими словами, что те эгрегориальные структуры, которые завязаны на Изосферу, более плотно курируют своих подопечных. <br><br><strong>ВОПРОС:</strong> С чем это связано? <br><strong>ОТВЕТ:</strong> Непосредственно с подчинением эгрегориальными структурами программам индивидуума. Второй момент, не сильно явный, опосредованный. Это забор энергии от индивидуума. В связи с тем, что программы, курируемые Изосферой, требуют, как для самой Изосферы, так и для определённых структур, энергетическую поддержку. Дополнительно мы бы сказали, что те эгрегориальные образования, которые курируются Изосферой несут более плотно насыщенные программы, которые тоже, в свою очередь, требуют определённой энергетической поддержки для своего функционирования. <br><br><strong>ВОПРОС:</strong> То есть, по сути, можно сказать, что идёт энергообмен между Ноосферой и реинкарнируемой душой и между Изосферой (как одной из ипостасей Ноосферы) и реинкарнируемой душой. И вот этот объем энергообмена - он разный? Но как это можно сформулировать? То есть, кто больше забирает и кто больше отдаёт? Ноосфера и Изосфера человеку или человек Изосфере и Ноосфере? <br><strong>ОТВЕТ:</strong> Чёткой границы здесь провести невозможно, потому как, в разные периоды времени… Ваш вопрос является с подтекстом, обесточивает ли Изосфера в течение реинкарнирования индивидуума. <br><br><strong>ВОПРОС:</strong> Нет, я имел виду, не обесточивание. Я имел в виду, как раз, баланс этого обмена. Он, в любом случае, будет нулевой. Или будет смещаться в минус или плюс Ноосферы и человека, Изосферы и человека? <br><strong>ОТВЕТ:</strong> И в одном и в другом случае баланс энергетический не смещается. Что касается Изосферных структур, то индивидуумы, которые в определённые периоды времени завязаны на эгрегориальные структуры, либо на программы, курируемые Изосферой, в эти периоды учатся восполнять свои энергозапасы. Как самостоятельно, так и при помощи окружающих людей и пространства, в том числе. И обесточивание индивидуума не происходит. Он отдает, и он берет, здесь взаимообмен. <br><br><strong>ВОПРОС:</strong> Я понял, что программы, в том числе, которые устанавливаются Изосферой, они позволяют делать забор и добор энергетики из окружающего пространства или от окружающих людей или сущностей. Так? <br><strong>ОТВЕТ:</strong> Да все верно. <br><br><strong>ВОПРОС:</strong> Следующий вопрос. Есть информация, что выше второго слоя Учителей располагаются курационные уровни. Существует ли иерархия среди Учителей кураторов. И чем одна ступень иерархии отличается от другой. То есть, как курируется конкретный человек? <br><strong>ОТВЕТ:</strong> Что касается иерархии…в плане курации человека или иерархии как самой составляющей Ноосферы? <br><br><strong>ВОПРОС:</strong> Самой составляющей, то есть внутренней иерархии. А как курируется человек, имеется в виду, наверное, какими слоями курируется и какие бывают варианты? <br><strong>ОТВЕТ:</strong> Варианты курации индивидуума могут быть различными, вплоть до седьмого уровня Учителей. Это зависит от тех программ, которые в данный период в индивидууме разворачиваются либо способны к разворачиванию. Здесь не принципиально. Что касается иерархии это единое целое и разграничения в этом целом по частям не существует. <br><br><strong>ВОПРОС:</strong> То есть, можно сказать, что внутреннее разделение - оно функциональное? <br><strong>ОТВЕТ:</strong> Да. Такого явного разделения как человек для себя может воспринимать, такого нет. Это единый механизм, который действует согласовано. <br><br><strong>ВОПРОС:</strong> Выходит, иерархия это понятие человека. Да? Но в любом случае и в космических структурах все равно есть иерархия? <br><strong>ОТВЕТ:</strong> Есть определенные цели и задачи, которые выполняются определенными видами структур. Есть определенные структуры, которые отвечают только за свой определенный участок работ. Есть определенные структуры, которые контролируют выполнение работ этих участков. <br><br><strong>ВОПРОС:</strong> К примеру, есть какие- либо слои. Либо, скажем так, есть части иерархии Ноосферы, которые принимают решение по тому или иному вопросу. И остальные должны его исполнять, то есть, это тоже по функциональному принципу. И этот слой или уровень Учителей, он принимает решение по этим вопросам и остальные, даже более высокие уровни, должны их выполнять? Или по-другому? Я правильно вас понял? <br><strong>ОТВЕТ:</strong> По аналогу сравнения это, примерно, как слесарь не может советовать плотнику, как ему лучше заколачивать гвоздь. <br><br><strong>ВОПРОС:</strong> Можно ли сказать, что в Ноосфере оперативное решение принимается по функциональному признаку? А принципиальное решение - по принципу совета, вече. Да? То есть, каждая функциональная единица или функциональная часть высказывается по данному вопросу. И потом, уже с энергетическим эффектом, появляется решение, которое выполняют все. Так? <br><strong>ОТВЕТ:</strong> Это подходит более близко. <br><br><strong>ВОПРОС:</strong> В Изосфере, распределение и иерархия подобны вышеописанной или там более жестко выстроено иерархическое сообщество? <br><strong>ОТВЕТ:</strong> Что касается Изосферы, принцип подобный, а жёсткость в плане того, что больше требуют у человека. <br><br><strong>ВОПРОС:</strong> Существуют, какие - либо права и обязанности кураторов Учителей по отношению к человеку, которого они курируют. Имеет человек, какие - либо права и обязанности по отношению к своему куратору? <br><strong>ОТВЕТ:</strong> Что касается прав и обязанностей одной из сторон, фактически, это дело добровольное. И никаких обязательств в человеческом понимании с печатью и росписью обеих сторон не происходит. Конечно, Ноосфера, в определённых ситуациях, может подталкивать индивидуума к принятию какого - либо решения, в котором она заинтересована. Этот принцип, так же, касается и Изосферы. Обязанности здесь больше ложатся на плечи индивидуума в выполнении тех программ, которые должны быть реализованы в течение текущей инкарнации. Что касается прав, с нашей точки зрения, права, это и есть обязательства. То есть, в любом случае, человек находясь в реинкарнировании, должен выполнить свои обязательства. С нашей точки зрения он не имеет ни морального, ни морально-этического права не выполнить их. <br><br><strong>ВОПРОС:</strong> Понятно. А если брать в разрезе обязательств самих Учительских структур по отношению к самой Ноосфере в отношении курации людей. Это обязательно для них или они сами выбирают, кого им курировать? <br><strong>ОТВЕТ:</strong> Курируются программы, а не индивидуумы. <br><br><strong>ВОПРОС:</strong> То есть, к примеру, есть некая функциональная программа. Под исполнение которой набирают души, инкарнируют их из ячеек. И эта программа контролирует их инкарнацию, а Учитель контролирует их действия через программу инкарнирующих душ? Так? <br><strong>ОТВЕТ:</strong> Да, это близко. <br><br><strong>ВОПРОС:</strong> В Изосфере, также? <br><strong>ОТВЕТ:</strong> В Изосфере курируются как программные комплексы, так и индивидуумы. Это те носители программ, которые более значимы в текущий момент. <br><br><strong>ВОПРОС:</strong> Я так понимаю, в Ноосфере тоже так может быть в исключительных случаях? <br><strong>ОТВЕТ:</strong> В исключительных – да, но в Ноосфере курируются больше именно программные комплексы, нежели индивидуумы. <br><br><strong>ВОПРОС:</strong> Вы хотите сказать, что в Изосфере более индивидуальный подход? <br><strong>ОТВЕТ:</strong> Мы бы сказали что да. <br><br><strong>ВОПРОС:</strong> Понятно, спасибо. Как можно организовать взаимодействие с Учителями со стороны человека, от чего зависит форма и уровень взаимодействия человека с Учителями? Как можно установить связь со своим куратором? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия непосредственной курации и выхода на курацию со стороны человека, это маловероятно, так как, основной интерес представляют только программы для реализации в текущей реинкарнации. Само по себе физическое тело, с определённым набором сознания, как для Ноосферы, Изосферы, так и для представителей Дальнего космоса, не имеет никакого значения. Попытаемся объяснить этот момент. Все что происходит в инкарнации, это сиюминутно меняется, оно изменчиво. В одну секунду времени вы можете миллион раз подумать о разном. Ваши планы, действия, мысли, меняются с такой быстротой, о которой вы не отдаёте себе отчёта. И все это не формируется в те программы, которые действительно важны для реализации и могут принести какой-то результирующий эффект. Поэтому те программы, которые были заложены до реинкарнирования, и которые имеют целесообразность быть развёрнутыми - именно те программы курируются. <br><br><strong>ВОПРОС:</strong> В принципе, смысл уловили. Только можно ли сказать, что непосредственная курация возможна только тогда когда сама личность, к примеру, она сложносоставная и состоит из нескольких душ и матриц. Когда её существование, по сути, и есть основное зерно программы. Ну, вот возьмём, как с Иисусом Христом, с Буддой, когда они являлись как искоркой для новой религии, для нового мировоззрения, вот так? <br><strong>ОТВЕТ:</strong> Мы об этом и говорили. Что курируется программный комплекс. <br><br><strong>ВОПРОС:</strong>Тогда мы вас правильно поняли, спасибо продолжаем. Учителя какого порядка выходят на контакт через посредника, от чего это зависит? <br><strong>ОТВЕТ:</strong> Давайте сразу расставим точки над «и». Что касается того проекта который вёл Александр это исключение из всех существующих норм и правил. Александру была дана возможность согласно его задачи выводить людей на разные слои Учителей. И получать информацию, брать информацию с разных уровней. Эта возможность давалась только коалиционно. Что касается остального проекта, глобального проекта человечества, опять же, повторимся, курируются разными уровнями, разными слоями Учительской системы разные программы, которые важны для реализации. И прямого выхода индивидуума на курирующую структуру не происходит. В большей части индивидуум не подозревает о том, что в своём мозгу он может общаться не с самим собой. Если таковые подозрения даже и возникают то, как правило, это считается заболеванием. Что касается новомодного всплеска общения с Силами и Учителями разных слоёв и разного крыла –то, по большей части, это определённый бум вызванный работой Александра. Реально существующих контактов, масса которых якобы происходит на сегодняшний момент, составляет мизерный процент. <br><br><strong>ВОПРОС:</strong> Я думаю 0,1- 0,2 процента, правильно? <br><strong>ОТВЕТ:</strong> Да, все верно, сотые процента. А остальное мания величия. <br><br><strong>ВОПРОС:</strong> То есть, если опять же правильно вас понял, если такой контакт и есть, он идёт через банк данных Ноосферы. Ну, к примеру, как подключение к одному из волноводов одного из проводов. Да? <br><strong>ОТВЕТ:</strong> Либо через эгрегориальные структуры. <br><br><strong>ВОПРОС:</strong> Есть информация, что Учителя второго порядка используют речевой канал общения только в исключительных случаях. Если так, то что для них является исключительным случаем и когда используется психографика? Несколько такой сумбурный вопрос. Но хотя бы что вы считаете здесь рациональным зерном? Ответьте,пожалуйста. <br><strong>ОТВЕТ:</strong> И опять же, что касается для не участников проекта Александра. В данном случае Учителя, и не только, но и представители разумных Сил Дальнего космоса, используют моменты подключения не только через психографику, но и через речевой канал. Мы бы сказали для какой-то степени убеждения. Убеждения большого количества масс. И в редких случаях это больше работает схема Изосферы непосредственного донесения вербальной информации до индивидуума, в котором она заинтересована. <br><br><strong>ВОПРОС:</strong> Причём в повелительном, скажем так, плане. Да? <br><strong>ОТВЕТ:</strong> Не всегда в повелительном, чаще в разъяснительном. <br><br><strong>ВОПРОС:</strong> Понятно, спасибо. В каких случаях и как часто человеку оказывается информационная, энергетическая, кураторская помощь спасения в кризисных ситуациях. Речь идёт, когда помимо программы Ангела хранителя или Сущности ангела хранителя, может ли подключатся куратор? <br><strong>ОТВЕТ:</strong> Что касается непосредственной курации со стороны, инициаторами которой являются сами Ноосферные, Изосферные структуры, либо представители Дальнего космоса, то, в этом случае, все зависит от того, насколько важен сам индивидуум со своими программами реализации. Бывают такие прецеденты, когда важна программа, но рассматривается момент её развития в разных кризисных ситуациях. В данном случае помощи от курирующих структур происходить не будет. Будет происходить только момент наблюдения. Опять же, все зависит от того, на каком этапе находится данная программа. Какие экспериментальные моменты проводятся с испытуемым. <br><br><strong>ВОПРОС:</strong> То есть, это чаще вопрос только корректировки программы, так? <br><strong>ОТВЕТ:</strong> По необходимости. Мы бы сказали, что да, такой вариант тоже возможен. <br><br><strong>ВОПРОС:</strong> Хорошо. Чем отличается курация со стороны Ноосферы, Изосферы и Дальнего космоса? <br><strong>ОТВЕТ:</strong> В каком смысле? <br><br><strong>ВОПРОС:</strong> К примеру, как сейчас, вы описали принцип курации Ноосферы и соответственно Изосферы. Это через программный комплекс, сформированный в некую программу. И идёт взаимодействие через неё. Если, допустим, представители Дальнего космоса выходят на инкарнируемые души. Это непосредственный контакт, через создаваемую программу либо, через заранее подсаженную программу. Каким образом происходит этот контакт, если он имеет место? <br><strong>ОТВЕТ:</strong> Вы не совсем уловили смысл того, о чем мы сейчас говорим. Изначально мы говорили, что курируется программный комплекс и программы, которые наиболее важны для развития. Не сам индивидуум, а именно программы. Поэтому взаимодействие со стороны, как Ноосферы, так и Изосферы и туда же относятся представители Дальнего космоса - одинаков. Курируется программный комплекс. <br><br><strong>ВОПРОС:</strong> Все понятно. Есть же исключения, но они только подтверждают правила. <br><strong>ОТВЕТ:</strong> Эти исключения составляют очень незначительный процент. <br><br><strong>ВОПРОС:</strong> Можно ли считать современные Земные информационные технологии, в частности глобальную сеть интернет, отражением или частью Ноосферы? Передан ли этот продукт человечеству или это плод достижения самого человечества. Можно ли провести аналогию связей взаимодействий идей и принципов работы интернет сетей с теми же связями в Ноосфере, соответственно и в Изосфере? <br><strong>ОТВЕТ:</strong> Что касается аналогии. По аналогии, это можно сравнить с Хроносферой. Принцип взаимодействия и разворачивания идентичен. <br><br><strong>ВОПРОС:</strong> Извините, я перебью – вы говорите о принципе разворачивания информации? <br><strong>ОТВЕТ:</strong> Да, информации. Что касается достояния авторства, можете считать пятьдесят на пятьдесят. Идея была подкинута и она была реализована. <br><br><strong>ВОПРОС:</strong> Понятно, спасибо. С какой целью и как происходит связь Ноосферы с другими цивилизациями? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия Ноосферы, с цивилизациями, говоря человеческим языком, существует определённый законодательный орган, который отвечает за свои функциональные обязанности. И выполняет только свою исключительную функцию. Что касается момента исполнения, обратной связи, то, с законодательным органом Планетарного разума считаются представители Дальнего космоса. <br><br><strong>ВОПРОС:</strong> То есть, это изначально создаваемая как функциональная программа для достижения определённой цели? Она выросла уже в некоего, можно сказать, игрока или предигрока, с которым уже считаются? <br><strong>ОТВЕТ:</strong> Да, с ними считаются. И, в принципе, таких жёстких указаний как, допустим, вам надо сделать вот это или это, здесь не происходит. То есть, существует момент как- бы рекомендательный. А дальше, на усмотрение этого законодательного органа, принимать это или не принимать. Жёстко могут подойти только Создатель и Триединые. <br><br><strong>ВОПРОС:</strong> Создатель и его создаваемые структуры? <br><strong>ОТВЕТ:</strong> Да. <br><br><strong>ВОПРОС:</strong> В каких тогда случаях, с какой целью, каким образом, Учительские образования связываются вот с иным разумом? То есть с игроками Дальнего космоса. <br><strong>ОТВЕТ:</strong> По сути, на данном этапе такой задачи не стоит как связь. То есть протекают определённые процессы, которые пока не достигли своей пиковой точки. Что касается глобального проекта Человечества, то есть тридцать процентов материала, который уже способен что-либо организовать. То есть прошёл определенный уровень информационного накопления и развития. <br><br><strong>ВОПРОС:</strong> А можно уточнить? На тридцать процентов, это те, что тянут на ту задачу на те цели, которые ставятся. Или тридцать процентов, это, какой-то объем душ, который должен быть набран. Душ, полностью обученных и готовых. Так? То есть этот объем заполнен только на тридцать процентов. Первое или второе? <br><strong>ОТВЕТ:</strong> Второе. <br><br><strong>ВОПРОС:</strong> Понятно. Тогда, немного уточним, можно ли сказать, что Ноосфера, она уже сама по себе структура, инкорпорированная в одну из структур Создателя? <br><strong>ОТВЕТ:</strong> Нет. Она ещё не достигла этого уровня. <br><br><strong>ВЕДУЩИЙ:</strong> Все понятно. <br><strong>ОТВЕТ:</strong> У неё свои функциональные обязанности. <br><br><strong>ВОПРОС:</strong> Последний вопрос. Откуда идёт воздействие на человека деструктивных Сил. В каких случаях и как Учителя препятствуют воздействию деструктивных Сил? Ну, здесь вопрос может, поставлен не совсем правильно. Видимо давайте я его перефразирую. То есть, если я правильно понимаю, то деструктивная Сила общается или работает обычно в этом плане через Изосферу? Правильно это можно понять? Или через Ноосферу тоже? Ну, когда нужно оказать воздействие на конкретных индивидуумов или программы. <br><strong>ОТВЕТ:</strong> Здесь задействуются оба варианта. В зависимости от целеполагания и задачи. <br><br><strong>ВОПРОС:</strong> И тоже конструктивных Сил касается? <br><strong>ОТВЕТ:</strong> Конструктивные силы в том числе. <br><br><strong>ВОПРОС:</strong> Тогда перефразирую, в каких случаях Учителя Ноосферы и Учителя Изосферы имеют право воспрепятствовать, к примеру, конструктивным и деструктивным Силам, когда они пытаются воздействовать на курируемые ими программы. <br><strong>ОТВЕТ:</strong> Несоответствие интересов. <br><strong>ВЕДУЩИЙ:</strong> Все понятно. Большое спасибо, был очень продуктивный разговор.&nbsp;</div>','<div><div class=\"xi-imgtable xi-imgtable--right\"><figure data-trix-attachment=\'{\"alignment\":\"right\",\"contentType\":\"image\",\"height\":140,\"url\":\"/storage/media/archive/8b8fb5524dba709605e0f931.png\",\"width\":200}\' data-trix-content-type=\"image\" class=\"attachment attachment--preview xi-float-right\"><a href=\"/storage/media/archive/8b8fb5524dba709605e0f931.png\" target=\"_blank\" rel=\"noopener noreferrer\"><img alt=\"Изображение к материалу «Сеанс с Силами 20140205» - №1\" src=\"/storage/media/archive/8b8fb5524dba709605e0f931.png\" width=\"200\" height=\"140\"></a></figure><table>\n<tbody><tr>\n<td><strong>Проект</strong>:\n</td>\n<td><em>\"<span class=\"glossary-term\" data-glossary-term=\"Ноосфера\" data-glossary-definition=\"Ноосфера: 1) в процессе эволюции человека с помощью Сил Дальнего Космоса была сформирована колоссальная энергоинформационная структура, объединяющая всё человечество в единый «организм». Руководствуясь Космическими Законами и полностью им соответствуя, Ноосфера контролирует эволюцию человечества, направляя его в русло формирования сообщества, также соответствующего этим Законам. Данное образование имеет сложное многоуровневое строение, каждый уровень которого представлен характерными для него носителями интеллекта – Учителями (см.). Верхние этажи этой «пирамиды» связаны с различными Силами Дальнего Космоса и в общепринятых человеческих понятиях смыкаются с представлениями о Боге. Данная «Сфера Разума» перекликается с гениальным предвидением Вернадского, поэтому по традиции названа Ноосферой. Источник: Книга &quot;Сфера Разума&quot;.2) Ноосфера - сложная разумная энергоинформационная структура, соответствующая Космическим Законам и способствующая эволюции человечества, способная к развитию и совершенствованию как самостоятельно, так и совместно с планетарным Разумом. По развитию и скорости информационного обмена на порядок опережает человеческое сообщество. Ноосфера создана конструктивными Силами Дальнего Космоса, в т.ч. как основа для создания единого планетарного разума, Соборной Души Разума. Обладает сложной эшелонированной структурой, функционально разделенной по уровням. Населена персонализированными составными монадами (Учителями). Имеет в составе сложные временные и энергетические структуры, банки информации. Осуществляет паритетный информационный обмен с другими Разумными системами Ближнего и Дальнего Космоса. Источник: &quot;Книга Живы&quot;.\" tabindex=\"0\">Ноосфера</span> -11\" Взаимодействие Ноосферы с людьми</em>\n</td></tr>\n<tr>\n<td><strong>Дата:</strong>\n</td>\n<td>5 февраля 2014 годa\n</td></tr>\n<tr>\n<td><strong>Ведущий:</strong>\n</td>\n<td>Олег\n</td></tr>\n<tr>\n<td><strong>Силы</strong>\n</td>\n<td>2 Кольцо\n</td></tr>\n<tr>\n<td><strong>Посредник</strong>\n</td>\n<td>Елена\n</td></tr>\n</tbody></table></div></div><div><strong>ВОПРОС:</strong> Как организовано информационное и энергетическое взаимодействие человека с Учителями со стороны Ноосферы, и какие уровни Учителей взаимодействуют с людьми? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия человека и Ноосферы, данное взаимодействие происходит через инкарнационную ячейку. В принципе, не имеет никакой роли это ячейка Последователь или ячейка Хранитель. Так как, информация хранится в этих двух ячейках и дублируется. В принципе, такой же уровень взаимодействия осуществляется и со стороны Изосферы. Непосредственно человеческая единица подвязана на два луча. Как на Ноосферу, так и на Изосферу. Взаимодействие происходит непосредственно с Учителями первого и, частично, второго порядка, что со стороны Ноосферы, так и со стороны Изосферы. Но со стороны Изосферы более интенсивно взаимодействует только первый уровень Учителей. <br><br><strong>ВОПРОС:</strong> Если мы ведём речь о точке подключения к Ноосфере через седьмую чакру, луч, выходящий на инкарнационную ячейку - это подключение к Ноосфере? <br><strong>ОТВЕТ:</strong> Да, к Ноосфере. <br><br><strong>ВОПРОС:</strong> А к Изосфере? <br><strong>ОТВЕТ:</strong> Через отражённого двойника. <br><br><strong>ВОПРОС:</strong> Через отражённого, то есть перевёрнутого, по сути дела? <br><strong>ОТВЕТ:</strong> Да. <br><br><strong>ВОПРОС:</strong> Этот луч идёт с третьей <span class=\"glossary-term\" data-glossary-term=\"Чакры\" data-glossary-definition=\"Чакры: 1) стабильные образования энергоструктуры человека, обеспечивающие энергетический баланс в организме за счёт обмена с внешней и внутренней средой, поддерживающие этим функционирование как отдельных органов, так и организма в целом. Кроме энергетических через чакры проходят также и информационные потоки. Источник: Книга &quot;Сфера Разума&quot;.2) Чакры (базовые энергоцентры организма) - комплекс из семи многофункциональных динамичных полевых образований, обеспечивающих энергетический баланс органов, энергетических структур и организма в целом за счёт обмена с внешней средой. С точки зрения эволюционного развития каждый энергоцентр можно представить как узкополосный резонатор - камертон, настраивающий информационно-эмоциональный (душевный) резонанс человека для согласования с процессами, происходящими как между индивидуумами, так и во внешней среде, что подразумевает отклик на возмущения планетарного и космического порядков. Чакры, как правило, располагаются в границах тела. Являются связующим звеном между организмом и окружающей средой, и из существующего разнообразия видов и спектров энергий отбирают, усваивают необходимые и удаляют ненужные или вредные для данного человека энергетические фрагменты (следствия болезней, внешней агрессии и др.). В свою очередь, эти шлаки могут утилизироваться другими организмами или неживыми системами. Источник: &quot;Книга Живы&quot;.\" tabindex=\"0\">чакры</span>? <br><strong>ОТВЕТ:</strong> Да, с третьей. Хотя здесь зависит и от того, каким образом расположен двойник в текущей инкарнации у человека. <br><br><strong>ВОПРОС:</strong> Разве бывают моменты когда двойник, может быть повернут под другим углом? <br><strong>ОТВЕТ:</strong> Да, все верно. <br><br><strong>ВОПРОС:</strong> Я понимаю, что это исключение, а от чего это может зависеть? <br><strong>ОТВЕТ:</strong> Это зависит от нескольких факторов. Первым фактором является - насколько человек относится к Изосфере, насколько он близок к Изосфере, так вернее будет сказать. Вторым основополагающим фактором является <span class=\"glossary-term\" data-glossary-term=\"Программа\" data-glossary-definition=\"Программа - под программой здесь понимается энергоинформационный комплекс, связанный в единое структурное образование, отражающее характеристики функциональных единиц органов и систем. На основе эталонных программ осуществляется периодический контроль работы организма; при выявленных отклонениях включается система коррекции. Программа – информационный комплекс на носителе, связанный в единое образование рядом признаков, отражающих отличительную черту какого-либо предмета или явления. Источник: Книга &quot;Сфера Разума&quot;.\" tabindex=\"0\">программа</span>. Программа, которую на данный момент отрабатывает индивид. Программы могут меняться по прошествии времени с интервалом в несколько лет. Индивид должен нарабатывать и отрабатывать программы как касающиеся развития Ноосферных структур, так касающиеся развития и Изосферных структур. <br><br><strong>ВОПРОС:</strong> И ещё момент касающийся Изосферы. Правильно ли я вас понимаю, что Изосфера и Ноосфера, если брать в некотором воспринимаемом нами пространственно временном континууме, находятся практически в одном и том же, скажем, месте, не точке? Они совмещены, скажем так? <br><strong>ОТВЕТ:</strong> Не совсем совмещены. <br><br><strong>ВОПРОС:</strong> Тогда как правильно? <br><strong>ОТВЕТ:</strong> Если рассматривать <span class=\"glossary-term\" data-glossary-term=\"Мерности\" data-glossary-definition=\"Мерности - ресурсы пространства, отличающиеся топологией, константами физических законов и разделенные энергетическими барьерами. Отдельные мерности пространства недоступны для Разумов до определенных ступеней развития, когда они, Разумы, смогут оперировать константами и коэффициентами собственных своих временных ключей и других структур, фиксирующих их существование в конкретном пространственном и временном континиуме. Источник: &quot;Книга Живы&quot;.\" tabindex=\"0\">мерности</span>, составляющие планетарное измерение, то по своему месту нахождения Ноосфера и Изосфера фактически граничат, но, находятся в разных плоскостях в разных плотностях. <br><br><strong>ВОПРОС:</strong> То есть, речь идёт о том, что они находятся в разных измерениях? У них разная частота колебания устойчивого состояния? <br><strong>ОТВЕТ:</strong> Да, всё верно. <br><br><strong>ВОПРОС:</strong> Все понятно. Спасибо. Дальше, следующий вопрос. Форма взаимодействия с человеком. Какие и когда формы взаимодействия применяются? Через группу людей, отдельных индивидуумов, через Эгрегоры, через инкарнационную ячейку, другие формы взаимодействия? Если взаимодействие через инкарнационную ячейку, то через ячейку Хранитель или ячейку Последователь? <br><strong>ОТВЕТ:</strong> Что касается ячейки. Вся информация о текущей инкарнации находится в ячейке Последователе. Но одновременно она дублируется в ячейке Хранителе. Поэтому какого-то глобального разделения в ячейках, по текущей инкарнации, не происходит. Взаимодействие, в основном, идёт через ячейку Последователь. Что касается взаимодействия учительской системы с человеком. Основное, как мы уже говорили ранее, это взаимодействие непосредственно через саму ячейку. Также взаимодействие с человеком идет с помощью эгрегориальных структур и непосредственно через окружающее пространство, именно не пространство - время, а пространство. В пространстве существуют некие точки, через которые, как при помощи рычагов, идет воздействие на человека. <br><br><strong>ВОПРОС:</strong> То есть, это возможно некие поля, да? Или программы в полевой форме? <br><strong>ОТВЕТ:</strong> Это точки, на которые Ноосфера либо Изосфера может давить, и будут происходить определенные события. <br><br><strong>ВОПРОС:</strong> Скажем так – это какие-то полевые образования, которые позволяют без непосредственного воздействия, а через опосредованное воздействие, подвинуть человека в этой инкарнации к тем или иным действиям. Да? <br><strong>ОТВЕТ:</strong> Близко. <br><br><strong>ВОПРОС:</strong> Хотел бы уточнить. Вот у нас есть прямая форма взаимодействия. К примеру, человек взаимодействует по лучу со своей ячейкой Последователь и через неё с Хранителем. С эгрегореальными структурами как это происходит? Луч идёт конкретно от эгрегориальной структуры, через седьмую чакру, к примеру, на биоэнергокристалл или на <span class=\"glossary-term\" data-glossary-term=\"Биоэкран\" data-glossary-definition=\"Биоэкран – высокоорганизованная часть полевой оболочки, контролирующая энергетические процессы в организме, выполняющая оценочно-регулирующие функции по отношению к процессу мышления, а также энергетически дублирующая головной мозг. Биоэкран фактически является нашим вторым, полевым, мозгом. С его помощью человек осуществляет двустороннюю связь с Ноосферой (см. Ноосфера), а также способен вступать в информационные контакты практически с любыми представителями Разумных Сил Космоса (см. Дальний Космос). Без преувеличения можно сказать, что данная энергоинформационная структура – окно человечества во внешний мир.\" tabindex=\"0\">биоэкран</span>? Или <span class=\"glossary-term\" data-glossary-term=\"Эгрегор\" data-glossary-definition=\"Эгрегор - энерго-информационно-временная структура, возникающая при сонаправленных действиях группы людей с общими устремлениями. Эгрегор также может создаваться и корректироваться Ноосферой или Конструктивными Силами. Существуют различные эгрегоры: религиозные, родоплеменные, клановые, магических орденов, некоторых философских учений, творческих школ, длительно и целеустремленно работающих коллективов, социальных движений и др. Происходит постоянное взаимное развитие эгрегора и индивидуумов через обмен информацией и энергиями, что способствует ускорению общего развития Разума. Сказанное нельзя применить в отношении деструктивных эгрегоров (масонства, различных сект, культов и пр.). Источник: &quot;Книга Живы&quot;.\" tabindex=\"0\">Эгрегор</span> использует луч, идущий на ячейку, и взаимодействие проходит через ячейку? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия эгрегориальных структур с человеком здесь достаточно иметь небольшое количество энергии данного эгрегора, для того, чтобы происходило взаимодействие. Что касается озвученной формы привязки по лучу, то здесь не видим никакого взаимодействия. Достаточно, как мы уже только что сказали, иметь причастность энергетически. <br><br><strong>ВОПРОС:</strong> То есть, чтобы совпадали вибрации, так? <br><strong>ОТВЕТ:</strong> Если в энергетике индивидуума будет находиться даже 5% энергетики эгрегориальной структуры, то уже будет происходить взаимодействие. Непосредственной привязки по лучу не происходит. <br><br><strong>ВОПРОС:</strong> Если я вас правильно понял, то здесь можно вернуться к тому понятию, которое ранее существовало до, скажем так, материалистической теории. Это понятие эфира. То есть некое распространение, скажем грубо, что-то вроде радиоволн, неких волновых посылов, импульсов, которые находят те души, так? У которых есть либо эти программные комплексы, либо эти закладки, либо совпадает по вибрациям, и тогда происходит взаимодействие, так? <br><strong>ОТВЕТ:</strong> Да все верно. <br><br><strong>ВОПРОС:</strong> А обратное взаимодействие. От души к эгрегориальной структуре. В такой же форме или это по принципу отражения, отражённого луча? <br><strong>ОТВЕТ:</strong> Всю ту информацию, которую прорабатывает в себе человек и изменения его энергетики - они автоматически отражаются в эгрегоре. То есть, получается энергетика человека несёт часть энергетики эгрегора. И они, как единое целое, взаимосвязаны. Но при этом, у человека существует ещё дополнительно один вариант взаимодействия с не очень крупным эгрегором. Это нахождение двух эгрегоров в одном большом и в другом, менее значимом. Это допускается, но не более. <br><br><strong>ВОПРОС:</strong> Но, я, всё-таки, прошу прощения, хотел бы ещё раз уточнить. Обратная взаимосвязь от человека к эгрегору происходит по принципу отражённого луча? Или по принципу - <span class=\"glossary-term\" data-glossary-term=\"Душа\" data-glossary-definition=\"Душа - зарождающаяся в Ноосфере саморазвивающаяся универсальная система энергетических, пространственных и мерностных констант и переменных, обусловленных процессами развития базовых, т.е. элементарных, единиц, наполняющих пространство и названных первичными излучениями, или первоизлучениями. Душа объединяет в себе полевую оболочку, полевой мозг, темпоральный (Т) мозг и другие энергоинформационные единицы. Собственно, Душа - это свод названных составляющих на протяжении всей череды инкарнаций. Душа человека обладает обширными возможностями самообучения, саморазвития, самовыражения, реализации, самоопределения, сохраняя при этом лабильность, гибкость, способность к трансформации всех своих составляющих. Реализованная Душа, то есть завершившая цикл инкарнаций и достигшая совершенства, обретает возможность самоопределения - существовать ли ей в пределах родного Разума, принимать участие в жизни других Разумов или отправиться в свободный поиск во Вселенной. Источник: &quot;Книга Живы&quot;.\" tabindex=\"0\">душа</span> сама испускает определённые волны? <br><strong>ОТВЕТ:</strong> По принципу прямой взаимосвязи. <br><br><strong>ВОПРОС:</strong> Всё-таки, эта программка? Создаётся некая программка, которая в ответ и посылает эти лучи, импульсы? <br><strong>ОТВЕТ:</strong> Происходит синхронизация энергетики индивидуума и энергетики эгрегориальной структуры. <br><br><strong>ВОПРОС:</strong> Хорошо, а если мы коснёмся Изосферы. То, взаимосвязь – подобна, как с Ноосферой или есть какие - то особенности? Как структуры? <br><strong>ОТВЕТ:</strong> Здесь есть определённые существенные различия. В данном случае, если эгрегориальная структура курируется непосредственно Изосферными структурами, то здесь более плотный контроль над количеством объёма энергии дублируемой эгрегором на величину, значительно превышающую количество энергии, которое взаимодействует с Ноосферными структурами. То есть, здесь эти объёмы доходят, в некоторых случаях, от 15 до 20-23 процентов. Можно сказать, другими словами, что те эгрегориальные структуры, которые завязаны на Изосферу, более плотно курируют своих подопечных. <br><br><strong>ВОПРОС:</strong> С чем это связано? <br><strong>ОТВЕТ:</strong> Непосредственно с подчинением эгрегориальными структурами программам индивидуума. Второй момент, не сильно явный, опосредованный. Это забор энергии от индивидуума. В связи с тем, что программы, курируемые Изосферой, требуют, как для самой Изосферы, так и для определённых структур, энергетическую поддержку. Дополнительно мы бы сказали, что те эгрегориальные образования, которые курируются Изосферой несут более плотно насыщенные программы, которые тоже, в свою очередь, требуют определённой энергетической поддержки для своего функционирования. <br><br><strong>ВОПРОС:</strong> То есть, по сути, можно сказать, что идёт энергообмен между Ноосферой и реинкарнируемой душой и между Изосферой (как одной из ипостасей Ноосферы) и реинкарнируемой душой. И вот этот объем энергообмена - он разный? Но как это можно сформулировать? То есть, кто больше забирает и кто больше отдаёт? Ноосфера и Изосфера человеку или человек Изосфере и Ноосфере? <br><strong>ОТВЕТ:</strong> Чёткой границы здесь провести невозможно, потому как, в разные периоды времени… Ваш вопрос является с подтекстом, обесточивает ли Изосфера в течение реинкарнирования индивидуума. <br><br><strong>ВОПРОС:</strong> Нет, я имел виду, не обесточивание. Я имел в виду, как раз, баланс этого обмена. Он, в любом случае, будет нулевой. Или будет смещаться в минус или плюс Ноосферы и человека, Изосферы и человека? <br><strong>ОТВЕТ:</strong> И в одном и в другом случае баланс энергетический не смещается. Что касается Изосферных структур, то индивидуумы, которые в определённые периоды времени завязаны на эгрегориальные структуры, либо на программы, курируемые Изосферой, в эти периоды учатся восполнять свои энергозапасы. Как самостоятельно, так и при помощи окружающих людей и пространства, в том числе. И обесточивание индивидуума не происходит. Он отдает, и он берет, здесь взаимообмен. <br><br><strong>ВОПРОС:</strong> Я понял, что программы, в том числе, которые устанавливаются Изосферой, они позволяют делать забор и добор энергетики из окружающего пространства или от окружающих людей или сущностей. Так? <br><strong>ОТВЕТ:</strong> Да все верно. <br><br><strong>ВОПРОС:</strong> Следующий вопрос. Есть информация, что выше второго слоя Учителей располагаются курационные уровни. Существует ли иерархия среди Учителей кураторов. И чем одна ступень иерархии отличается от другой. То есть, как курируется конкретный человек? <br><strong>ОТВЕТ:</strong> Что касается иерархии…в плане курации человека или иерархии как самой составляющей Ноосферы? <br><br><strong>ВОПРОС:</strong> Самой составляющей, то есть внутренней иерархии. А как курируется человек, имеется в виду, наверное, какими слоями курируется и какие бывают варианты? <br><strong>ОТВЕТ:</strong> Варианты курации индивидуума могут быть различными, вплоть до седьмого уровня Учителей. Это зависит от тех программ, которые в данный период в индивидууме разворачиваются либо способны к разворачиванию. Здесь не принципиально. Что касается иерархии это единое целое и разграничения в этом целом по частям не существует. <br><br><strong>ВОПРОС:</strong> То есть, можно сказать, что внутреннее разделение - оно функциональное? <br><strong>ОТВЕТ:</strong> Да. Такого явного разделения как человек для себя может воспринимать, такого нет. Это единый механизм, который действует согласовано. <br><br><strong>ВОПРОС:</strong> Выходит, иерархия это понятие человека. Да? Но в любом случае и в космических структурах все равно есть иерархия? <br><strong>ОТВЕТ:</strong> Есть определенные цели и задачи, которые выполняются определенными видами структур. Есть определенные структуры, которые отвечают только за свой определенный участок работ. Есть определенные структуры, которые контролируют выполнение работ этих участков. <br><br><strong>ВОПРОС:</strong> К примеру, есть какие- либо слои. Либо, скажем так, есть части иерархии Ноосферы, которые принимают решение по тому или иному вопросу. И остальные должны его исполнять, то есть, это тоже по функциональному принципу. И этот слой или уровень Учителей, он принимает решение по этим вопросам и остальные, даже более высокие уровни, должны их выполнять? Или по-другому? Я правильно вас понял? <br><strong>ОТВЕТ:</strong> По аналогу сравнения это, примерно, как слесарь не может советовать плотнику, как ему лучше заколачивать гвоздь. <br><br><strong>ВОПРОС:</strong> Можно ли сказать, что в Ноосфере оперативное решение принимается по функциональному признаку? А принципиальное решение - по принципу совета, вече. Да? То есть, каждая функциональная единица или функциональная часть высказывается по данному вопросу. И потом, уже с энергетическим эффектом, появляется решение, которое выполняют все. Так? <br><strong>ОТВЕТ:</strong> Это подходит более близко. <br><br><strong>ВОПРОС:</strong> В Изосфере, распределение и иерархия подобны вышеописанной или там более жестко выстроено иерархическое сообщество? <br><strong>ОТВЕТ:</strong> Что касается Изосферы, принцип подобный, а жёсткость в плане того, что больше требуют у человека. <br><br><strong>ВОПРОС:</strong> Существуют, какие - либо права и обязанности кураторов Учителей по отношению к человеку, которого они курируют. Имеет человек, какие - либо права и обязанности по отношению к своему куратору? <br><strong>ОТВЕТ:</strong> Что касается прав и обязанностей одной из сторон, фактически, это дело добровольное. И никаких обязательств в человеческом понимании с печатью и росписью обеих сторон не происходит. Конечно, Ноосфера, в определённых ситуациях, может подталкивать индивидуума к принятию какого - либо решения, в котором она заинтересована. Этот принцип, так же, касается и Изосферы. Обязанности здесь больше ложатся на плечи индивидуума в выполнении тех программ, которые должны быть реализованы в течение текущей инкарнации. Что касается прав, с нашей точки зрения, права, это и есть обязательства. То есть, в любом случае, человек находясь в реинкарнировании, должен выполнить свои обязательства. С нашей точки зрения он не имеет ни морального, ни морально-этического права не выполнить их. <br><br><strong>ВОПРОС:</strong> Понятно. А если брать в разрезе обязательств самих Учительских структур по отношению к самой Ноосфере в отношении курации людей. Это обязательно для них или они сами выбирают, кого им курировать? <br><strong>ОТВЕТ:</strong> Курируются программы, а не индивидуумы. <br><br><strong>ВОПРОС:</strong> То есть, к примеру, есть некая функциональная программа. Под исполнение которой набирают души, инкарнируют их из ячеек. И эта программа контролирует их инкарнацию, а Учитель контролирует их действия через программу инкарнирующих душ? Так? <br><strong>ОТВЕТ:</strong> Да, это близко. <br><br><strong>ВОПРОС:</strong> В Изосфере, также? <br><strong>ОТВЕТ:</strong> В Изосфере курируются как программные комплексы, так и индивидуумы. Это те носители программ, которые более значимы в текущий момент. <br><br><strong>ВОПРОС:</strong> Я так понимаю, в Ноосфере тоже так может быть в исключительных случаях? <br><strong>ОТВЕТ:</strong> В исключительных – да, но в Ноосфере курируются больше именно программные комплексы, нежели индивидуумы. <br><br><strong>ВОПРОС:</strong> Вы хотите сказать, что в Изосфере более индивидуальный подход? <br><strong>ОТВЕТ:</strong> Мы бы сказали что да. <br><br><strong>ВОПРОС:</strong> Понятно, спасибо. Как можно организовать взаимодействие с Учителями со стороны человека, от чего зависит форма и уровень взаимодействия человека с Учителями? Как можно установить связь со своим куратором? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия непосредственной курации и выхода на курацию со стороны человека, это маловероятно, так как, основной интерес представляют только программы для реализации в текущей реинкарнации. Само по себе физическое тело, с определённым набором сознания, как для Ноосферы, Изосферы, так и для представителей Дальнего космоса, не имеет никакого значения. Попытаемся объяснить этот момент. Все что происходит в инкарнации, это сиюминутно меняется, оно изменчиво. В одну секунду времени вы можете миллион раз подумать о разном. Ваши планы, действия, мысли, меняются с такой быстротой, о которой вы не отдаёте себе отчёта. И все это не формируется в те программы, которые действительно важны для реализации и могут принести какой-то результирующий эффект. Поэтому те программы, которые были заложены до реинкарнирования, и которые имеют целесообразность быть развёрнутыми - именно те программы курируются. <br><br><strong>ВОПРОС:</strong> В принципе, смысл уловили. Только можно ли сказать, что непосредственная <span class=\"glossary-term\" data-glossary-term=\"Курация\" data-glossary-definition=\"Курация (человека конструктивной Космической Силой) - принятие КС ответственности за результаты действий человека в течение текущей жизни или на протяжении нескольких жизней, и предполагает ответственность за жизнь и душевное развитие человека. Это не снимает ответственности с человека в случаях нарушения им законов причинно-следственных зависимостей, но может благоприятно ска- заться на проработке негативных кармических зависимостей прошлых жизней. Курация возникает в случае совпадения устремлений и дествий человека и КС. В случаях всех конструктивных КС обязательно двустороннее выраженное осознанное согласие о будущих действиях с разъяснением со стороны КС общих задач, перспектив и т.д. Тем самым соблюдаются основы свободы выбора. На большую часть человечества распространяется курация Учителей Ноосферы. Примечание. Курация человека деструктивными Силами предполагает совершенно иные взаимоотношения. Источник: &quot;Книга Живы&quot;.\" tabindex=\"0\">курация</span> возможна только тогда когда сама личность, к примеру, она сложносоставная и состоит из нескольких душ и матриц. Когда её существование, по сути, и есть основное зерно программы. Ну, вот возьмём, как с Иисусом Христом, с Буддой, когда они являлись как искоркой для новой религии, для нового мировоззрения, вот так? <br><strong>ОТВЕТ:</strong> Мы об этом и говорили. Что курируется программный комплекс. <br><br><strong>ВОПРОС:</strong>Тогда мы вас правильно поняли, спасибо продолжаем. <span class=\"glossary-term\" data-glossary-term=\"Учителя\" data-glossary-definition=\"Учителя: 1) представители Сил Ближнего Космоса; энергоинформационные сущности Ноосферы (см.). Учителя первого порядка представляют собой конгломерат из семи Ноосферных инкарнационных ячеек (см.), обладают мощным интеллектом и способны существовать несколько тысячелетий. Формирование первой такой структуры завершилось ко времени рождения Христа. Учителя полностью отвечают Космическим Законам. Они обладают определённой индивидуальностью, позволяющей выполнять каждому из них только ему присущие функции. Всего таких структур около трёхсот. 2) Учитель - разумная монада Ноосферы Источник: &quot;Книга Живы&quot;.3) обобщённое название конструктивных сущностей: архангелы, ангелы-хранители и т.п.\" tabindex=\"0\">Учителя</span> какого порядка выходят на контакт через посредника, от чего это зависит? <br><strong>ОТВЕТ:</strong> Давайте сразу расставим точки над «и». Что касается того проекта который вёл Александр это исключение из всех существующих норм и правил. Александру была дана возможность согласно его задачи выводить людей на разные слои Учителей. И получать информацию, брать информацию с разных уровней. Эта возможность давалась только коалиционно. Что касается остального проекта, глобального проекта человечества, опять же, повторимся, курируются разными уровнями, разными слоями Учительской системы разные программы, которые важны для реализации. И прямого выхода индивидуума на курирующую структуру не происходит. В большей части индивидуум не подозревает о том, что в своём мозгу он может общаться не с самим собой. Если таковые подозрения даже и возникают то, как правило, это считается заболеванием. Что касается новомодного всплеска общения с Силами и Учителями разных слоёв и разного крыла –то, по большей части, это определённый бум вызванный работой Александра. Реально существующих контактов, масса которых якобы происходит на сегодняшний момент, составляет мизерный процент. <br><br><strong>ВОПРОС:</strong> Я думаю 0,1- 0,2 процента, правильно? <br><strong>ОТВЕТ:</strong> Да, все верно, сотые процента. А остальное мания величия. <br><br><strong>ВОПРОС:</strong> То есть, если опять же правильно вас понял, если такой контакт и есть, он идёт через банк данных Ноосферы. Ну, к примеру, как подключение к одному из волноводов одного из проводов. Да? <br><strong>ОТВЕТ:</strong> Либо через эгрегориальные структуры. <br><br><strong>ВОПРОС:</strong> Есть информация, что Учителя второго порядка используют речевой канал общения только в исключительных случаях. Если так, то что для них является исключительным случаем и когда используется психографика? Несколько такой сумбурный вопрос. Но хотя бы что вы считаете здесь рациональным зерном? Ответьте,пожалуйста. <br><strong>ОТВЕТ:</strong> И опять же, что касается для не участников проекта Александра. В данном случае Учителя, и не только, но и представители разумных Сил Дальнего космоса, используют моменты подключения не только через психографику, но и через речевой канал. Мы бы сказали для какой-то степени убеждения. Убеждения большого количества масс. И в редких случаях это больше работает схема Изосферы непосредственного донесения вербальной информации до индивидуума, в котором она заинтересована. <br><br><strong>ВОПРОС:</strong> Причём в повелительном, скажем так, плане. Да? <br><strong>ОТВЕТ:</strong> Не всегда в повелительном, чаще в разъяснительном. <br><br><strong>ВОПРОС:</strong> Понятно, спасибо. В каких случаях и как часто человеку оказывается информационная, энергетическая, кураторская помощь спасения в кризисных ситуациях. Речь идёт, когда помимо программы Ангела хранителя или Сущности ангела хранителя, может ли подключатся куратор? <br><strong>ОТВЕТ:</strong> Что касается непосредственной курации со стороны, инициаторами которой являются сами Ноосферные, Изосферные структуры, либо представители Дальнего космоса, то, в этом случае, все зависит от того, насколько важен сам индивидуум со своими программами реализации. Бывают такие прецеденты, когда важна программа, но рассматривается момент её развития в разных кризисных ситуациях. В данном случае помощи от курирующих структур происходить не будет. Будет происходить только момент наблюдения. Опять же, все зависит от того, на каком этапе находится данная программа. Какие экспериментальные моменты проводятся с испытуемым. <br><br><strong>ВОПРОС:</strong> То есть, это чаще вопрос только корректировки программы, так? <br><strong>ОТВЕТ:</strong> По необходимости. Мы бы сказали, что да, такой вариант тоже возможен. <br><br><strong>ВОПРОС:</strong> Хорошо. Чем отличается курация со стороны Ноосферы, Изосферы и Дальнего космоса? <br><strong>ОТВЕТ:</strong> В каком смысле? <br><br><strong>ВОПРОС:</strong> К примеру, как сейчас, вы описали принцип курации Ноосферы и соответственно Изосферы. Это через программный комплекс, сформированный в некую программу. И идёт взаимодействие через неё. Если, допустим, представители Дальнего космоса выходят на инкарнируемые души. Это непосредственный контакт, через создаваемую программу либо, через заранее подсаженную программу. Каким образом происходит этот контакт, если он имеет место? <br><strong>ОТВЕТ:</strong> Вы не совсем уловили смысл того, о чем мы сейчас говорим. Изначально мы говорили, что курируется программный комплекс и программы, которые наиболее важны для развития. Не сам индивидуум, а именно программы. Поэтому взаимодействие со стороны, как Ноосферы, так и Изосферы и туда же относятся представители Дальнего космоса - одинаков. Курируется программный комплекс. <br><br><strong>ВОПРОС:</strong> Все понятно. Есть же исключения, но они только подтверждают правила. <br><strong>ОТВЕТ:</strong> Эти исключения составляют очень незначительный процент. <br><br><strong>ВОПРОС:</strong> Можно ли считать современные Земные информационные технологии, в частности глобальную сеть интернет, отражением или частью Ноосферы? Передан ли этот продукт человечеству или это плод достижения самого человечества. Можно ли провести аналогию связей взаимодействий идей и принципов работы интернет сетей с теми же связями в Ноосфере, соответственно и в Изосфере? <br><strong>ОТВЕТ:</strong> Что касается аналогии. По аналогии, это можно сравнить с Хроносферой. Принцип взаимодействия и разворачивания идентичен. <br><br><strong>ВОПРОС:</strong> Извините, я перебью – вы говорите о принципе разворачивания информации? <br><strong>ОТВЕТ:</strong> Да, информации. Что касается достояния авторства, можете считать пятьдесят на пятьдесят. Идея была подкинута и она была реализована. <br><br><strong>ВОПРОС:</strong> Понятно, спасибо. С какой целью и как происходит связь Ноосферы с другими цивилизациями? <br><strong>ОТВЕТ:</strong> Что касается взаимодействия Ноосферы, с цивилизациями, говоря человеческим языком, существует определённый законодательный орган, который отвечает за свои функциональные обязанности. И выполняет только свою исключительную функцию. Что касается момента исполнения, обратной связи, то, с законодательным органом Планетарного разума считаются представители Дальнего космоса. <br><br><strong>ВОПРОС:</strong> То есть, это изначально создаваемая как функциональная программа для достижения определённой цели? Она выросла уже в некоего, можно сказать, игрока или предигрока, с которым уже считаются? <br><strong>ОТВЕТ:</strong> Да, с ними считаются. И, в принципе, таких жёстких указаний как, допустим, вам надо сделать вот это или это, здесь не происходит. То есть, существует момент как- бы рекомендательный. А дальше, на усмотрение этого законодательного органа, принимать это или не принимать. Жёстко могут подойти только Создатель и Триединые. <br><br><strong>ВОПРОС:</strong> Создатель и его создаваемые структуры? <br><strong>ОТВЕТ:</strong> Да. <br><br><strong>ВОПРОС:</strong> В каких тогда случаях, с какой целью, каким образом, Учительские образования связываются вот с иным разумом? То есть с игроками Дальнего космоса. <br><strong>ОТВЕТ:</strong> По сути, на данном этапе такой задачи не стоит как связь. То есть протекают определённые процессы, которые пока не достигли своей пиковой точки. Что касается глобального проекта Человечества, то есть тридцать процентов материала, который уже способен что-либо организовать. То есть прошёл определенный уровень информационного накопления и развития. <br><br><strong>ВОПРОС:</strong> А можно уточнить? На тридцать процентов, это те, что тянут на ту задачу на те цели, которые ставятся. Или тридцать процентов, это, какой-то объем душ, который должен быть набран. Душ, полностью обученных и готовых. Так? То есть этот объем заполнен только на тридцать процентов. Первое или второе? <br><strong>ОТВЕТ:</strong> Второе. <br><br><strong>ВОПРОС:</strong> Понятно. Тогда, немного уточним, можно ли сказать, что Ноосфера, она уже сама по себе структура, инкорпорированная в одну из структур Создателя? <br><strong>ОТВЕТ:</strong> Нет. Она ещё не достигла этого уровня. <br><br><strong>ВЕДУЩИЙ:</strong> Все понятно. <br><strong>ОТВЕТ:</strong> У неё свои функциональные обязанности. <br><br><strong>ВОПРОС:</strong> Последний вопрос. Откуда идёт воздействие на человека деструктивных Сил. В каких случаях и как Учителя препятствуют воздействию деструктивных Сил? Ну, здесь вопрос может, поставлен не совсем правильно. Видимо давайте я его перефразирую. То есть, если я правильно понимаю, то деструктивная Сила общается или работает обычно в этом плане через Изосферу? Правильно это можно понять? Или через Ноосферу тоже? Ну, когда нужно оказать воздействие на конкретных индивидуумов или программы. <br><strong>ОТВЕТ:</strong> Здесь задействуются оба варианта. В зависимости от целеполагания и задачи. <br><br><strong>ВОПРОС:</strong> И тоже конструктивных Сил касается? <br><strong>ОТВЕТ:</strong> Конструктивные силы в том числе. <br><br><strong>ВОПРОС:</strong> Тогда перефразирую, в каких случаях Учителя Ноосферы и Учителя Изосферы имеют право воспрепятствовать, к примеру, конструктивным и деструктивным Силам, когда они пытаются воздействовать на курируемые ими программы. <br><strong>ОТВЕТ:</strong> Несоответствие интересов. <br><strong>ВЕДУЩИЙ:</strong> Все понятно. Большое спасибо, был очень продуктивный разговор. </div>','page','published',1,0,0,'archive_wiki','https://web.archive.org/web/20231207153924/http://www.x-intellect.org/wiki/index.php?title=%D0%A1%D0%B5%D0%B0%D0%BD%D1%81_%D1%81_%D0%A1%D0%B8%D0%BB%D0%B0%D0%BC%D0%B8_20140205','{\"meta_title\": \"Сеанс с Силами 20140205 — X-Intellect\", \"schema_type\": \"Article\", \"meta_description\": \"Проект: \'\\\"Ноосфера -11\\\" Взаимодействие Ноосферы с людьми Дата: 5 февраля 2014 годa Ведущий: Олег Силы 2 Кольцо Посредник Елена ВОПРОС: Как организовано информ…\"}',0,'2014-02-04 20:00:00','2020-01-23','2026-07-14 15:03:50','2026-07-18 18:11:32'),(301,14,'Проект: \"Человек - Земля - Космос: Продолжение\" (глава 2) У.С.Э. ч. 1-6','seans-s-silami-20140828','Проект: \"Человек - Земля - Космос 2014\" Управление собственной энергетикой, ч.1 Дата: 28.08.2014 Ведущий: Татьяна Силы Зеленые, Меднокожие Посредник Светлана Глаз С текстовой частью ченнеллинга можно…',NULL,'<div><em>Это продолжение проекта \"Человек - Земля - Космос 2014\" (глава 2), первую главу проекта смотрите </em><a href=\"https://x-intellect.