INSERT INTO `sections` VALUES (1,NULL,'Вики','wiki','<div>Ноосфера, внеземной разум и внеземные цивилизации - информационные спонсоры нашего проекта. Мы сотрудничаем с ними уже более 30 лет в различных областях: энергетика, экстрасенсорное развитие, парапсихология, биоэнергоинформатика. В результате этой работы создана программа обучения и развития экстрасенсорных возможностей с положительными результатaми. Здесь вы найдёте аудио-записи сеансов ченнелинга и можете принять участие в таком сеансе, задать вопрос Внеземному Разуму и получить ответ.</div><div><br><strong>Приветствие от представителей Внеземного Разума</strong>:&nbsp;</div><blockquote>\"Мы рады приветствовать всех посетителей сайта: как новичков, так и тех, кто работает с нами давно. В особенности благодарим постоянных членов команды, так или иначе работающих на благо и процветание Ваших стран, а также человечества в целом. Мы считаем, что развиваясь самостоятельно, Вы помогаете развиваться окружающим Вас людям. Будьте настойчивы в достижении целей, не останавливайтесь перед трудностями и не давайте себе никаких поблажек. Надеемся на дальнейшую совместную плодотворную работу и думаем, что в конечном итоге Ваши желания будут удовлетворены.\"</blockquote>',4,1,1,'2026-07-08 05:32:26','2026-07-15 16:31:29'),(2,NULL,'Библиотека','library','Книги проекта: «Сфера Разума» А. Глаза, «За окраиной мира, бытия и сознания» В. Зорева и рекомендуемая литература.',5,1,1,'2026-07-08 05:32:26','2026-07-09 10:10:22'),(3,NULL,'Статьи','articles','Обобщающий раздел, где собраны материалы сайта вне разделов и вики: статьи, новости, дайджесты и другое, а также страницы памяти об основателе - Александре Георгиевиче Глазе.',6,1,1,'2026-07-08 05:32:26','2026-07-13 12:05:47'),(4,NULL,'Курсы','courses','<div>Архивы записей курсов Александра Глаза, находящиеся в открытом доступе с 2015 года.</div><h3>Почему эти материалы здесь?</h3><div>Так как раскрытие информации уже произошло, а сайт был недоступен более года, все доступные материалы собраны в одном месте - чтобы они не потерялись окончательно.&nbsp;<br><br>По интернету гуляют разные версии, но для публикации на сайте выбрана версия без личных данных участников. Материалы размещены в информационных и архивных целях.&nbsp;</div><h3>Важно!</h3><div>Если техники еще доступны для выполнения, то значит использование методик А. Глаза и его единомышленников еще отслеживается. Использование техник во вред другим или не по назначению влечет за собой ответственность, за это придется отвечать. Как писал автор поста с архивами курсов: <em>«Сразу предупреждаю, что если вы будете использовать эти знания для корысти, то вам настучат по башке…»</em></div><h3>Где еще найти записи?</h3><div>Записи курсов загружены пользователем afromu (личная информация участников курса удалена): <a href=\"https://afromu.livejournal.com/11669.html\">публикация в LiveJournal</a>. Если ссылка не открывается - есть <a href=\"https://web.archive.org/web/20260622111302/https://afromu.livejournal.com/11669.html\">копия в веб-архиве</a>. Файлы курсов продублировал на <a href=\"https://disk.yandex.ru/d/E9uI6yzVYZngaQ#_blank\">Яндекс Диск</a>.&nbsp;</div>',7,1,1,'2026-07-08 05:32:26','2026-07-27 04:47:49'),(5,NULL,'Приветствие','hello','Аудио-приветствия и пожелания от представителей Внеземного Разума по случаю открытия старого сайта, переданные через Посредников. Актуально и для нового ресурса.',1,1,1,'2026-07-08 05:32:26','2026-07-13 06:09:14'),(6,NULL,'Правила','rules','<div>Правила сайта X-INTELLECT и правовая информация.</div>',3,1,0,'2026-07-08 05:32:26','2026-07-27 18:39:52'),(8,NULL,'О центре','about','Идея, основы и цели центра X-INTELLECT - как их описывала команда проекта и то, каким проект является сейчас.',2,1,1,'2026-07-08 05:32:26','2026-07-14 12:57:42'),(9,NULL,'Архив форума','forum','Восстановление форума (phpBB) из архивных копий afromu от 2015 года - служит для демонстрации и сохранения обсуждений участников и сотрудников проекта. Регистрации и обсуждения отключены. Новые чаты и обсуждения ищите на странице - <a href=\"/about/contacts\" target=\"_blank\">Ресурсы проекта</a>.',9,1,0,'2026-07-08 05:32:26','2026-07-13 06:19:11'),(10,NULL,'Проекты','projects','<div>В процессе подготовки проектов, Центр «Х — Интеллект» использует уникальную информацию, полученную от различных внеземных разумов. В рамках каждого проекта, полученная информация анализируется, отрабатывается при необходимости, и интегрируется с существующими знанием, опытом и практиками в изучаемом направлении.&nbsp;<br>Главным и конечным этапом каждого проекта является поиск прикладного применения полученных разработок и результатов:&nbsp;</div><ul><li>«Душа»</li><li>«Ноосфера»</li><li>«Человек-Земля-Космос»</li><li>«Управление собственной энергетикой»</li><li>Проект «Картины Ноосферы»</li><li>Проект «Содружество» выполнен частично и закрыт из-за изменившихся политических и экономических условий.&nbsp;</li></ul><div>Вопросы и ответы общего или познавательного плана, заданные Силам во время ченнелингов, публикуются на сайте. Ведущие проектов заблаговременно готовят вопросы Силам и подготавливают для опубликования ответы.</div>',3,1,1,'2026-07-09 15:47:44','2026-07-15 03:08:17'),(11,3,'Дайджесты','daidzesty','<div>Полные и краткие страницы дайджестов. В полных версиях вы можете прочитать дайджест на сайте, в кратких (с пометкой \"Анонс\") - посмотреть доп. материалы (при наличии) и скачать дайджест для просмотра оффлайн.</div>',1,1,0,'2026-07-14 19:36:40','2026-07-19 21:05:13'),(12,1,'Общий раздел','obshhii-razdel','<div>Обобщающий раздел. Полный список страниц ВИКИ - <a href=\"/wiki#_blank\">здесь</a>.</div>',1,1,0,'2026-07-14 19:36:40','2026-07-19 11:50:08'),(13,1,'Проекты (Вики)','proekty',NULL,2,1,0,'2026-07-14 19:36:40','2026-08-14 06:18:18'),(14,1,'Сеансы','seansy',NULL,3,1,0,'2026-07-14 19:36:40','2026-07-14 19:36:40'),(15,10,'Целительство','celitelstvo-proekt',NULL,7,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(16,10,'Душа','dusha',NULL,1,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(17,10,'Мужчина и Женщина','muzhchina-i-zhenshhina',NULL,4,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(18,10,'Ноосфера','noosfera-proekt',NULL,2,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(19,10,'Изосфера и параллельные миры','izosfera',NULL,3,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(20,10,'Картины Учителей Ноосферы','kartiny-uchitelei',NULL,5,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(21,10,'Биоэкран','bioekran-proekt',NULL,6,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(22,10,'Эталонизация','etalonizaciia',NULL,8,1,0,'2026-07-14 20:08:09','2026-07-14 20:08:09'),(23,3,'Памяти А. Глаза','mag','<div>Раздел посвящён памяти Александра Георгиевича Глаза — основателя проекта Х-ИНТЕЛЛЕКТ. В нём представлены архивные материалы: воспоминания, сообщения о годовщинах со дня его ухода, а также информация о книге-воспоминании, которую создали родные, друзья и единомышленники.&nbsp;</div>',2,1,0,'2026-07-17 03:54:32','2026-07-19 21:06:38'),(24,10,'Человек — Земля — Космос','chelovek-zemlya-kosmos','<div>Один из последних проектов команды X-Intellect. Для удобства навигации сортируйте материалы по дате (в фильтре внизу сначала идут старые), тогда порядок будет правильным.<br><br>Изначально название частей проекта вносило некоторую путаницу, поэтому в новой версии сайта проект условно поделен на две главы:<br>1. Человек - Земля - Космос (2014, 1 глава).<br>2. Человек - Земля - Космос: Управление собственной энергетикой (У.С.Э., 2 глава).&nbsp;</div>',9,1,0,'2026-07-17 10:31:28','2026-10-01 12:52:50');
